programs.sol:
"""Approximate an opening-expression delimiter detector.

A separated '(' is strongest after operators, control-flow keywords and
English function words, but weak after content words and negative after digits.
The previous token supplies this local grammatical cue. Parentheses merged
with a following identifier, quote, operator or newline have separate gains;
longer identifiers are slightly stronger. Square brackets reuse the context
cue at lower strength. Empty delimiter pairs are suppressed. Two small extra
responses cover multiplication followed by '(' and the token 'self'.

Only the previous token is remembered, resetting at document boundaries.
"""
READS = ()

CONTROL_WORDS = frozenset('if for while catch foreach return except elif'.split())
FUNCTION_WORDS = frozenset('''
and or is are was were be been being as by of from to at in on with without
between through into over under after before than that which the this these
those an not so then because since although whether both either neither
'''.split())


def separated_open(previous):
    """Distinguish an expression start from a parenthetical annotation."""
    p = previous.strip()
    if not previous:
        return 1.47
    if not p:
        return 0.95
    if p[-1:].isdigit():
        return -0.10
    if p.endswith('='):
        return 3.0 if previous[:1].isspace() else 2.5
    if p.endswith('+'):
        return 2.8 if previous[:1].isspace() else 1.9
    if p.endswith(('-', '/', '<<', '>>', '=>')):
        return 2.4 if previous[:1].isspace() else 1.9
    if p.endswith((':', '(', '[', '<', '>')) or p in {'&&', '||', '→', '⇒'}:
        return 2.15
    if p.endswith(','):
        return 1.8
    if p.endswith(';'):
        return 1.5
    if p.endswith('.'):
        return 1.0
    if p in {'−', '–', '—', '≥', '≤', '≠', '±', '^', '|', '&', '~'}:
        return 1.9
    if p.endswith('*'):
        return 1.85 if previous[:1].isspace() else 1.3
    if p.lower() in CONTROL_WORDS:
        return 2.15 if previous[:1].isspace() or len(p) > 2 else 1.65
    if p.lower() in FUNCTION_WORDS:
        return 1.95 if previous[:1].isspace() else 0.5
    if p in {'a', 'you', 'them', 'it', 'we', 'he', 'she', 'they'}:
        return 0.6 if previous[:1].isspace() else 0.1
    if p.endswith((')', ']', '}')):
        return 0.35
    if p == '%':
        return 2.0 if previous[:1].isspace() else 0.4
    if p in {'?', '!'}:
        return 0.8
    return 0.15


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    text = token.lstrip()
    value = 0.0
    if text == '(':
        if token != text:
            value = separated_open(previous)
        else:
            p = previous.strip()
            if p[-1:].isdigit():
                value = 0.25
            elif len(p) == 1 and p.isalpha():
                value = 0.55
            elif p.isalpha():
                value = 0.75 if p.istitle() else 1.1
            elif p.startswith('.'):
                value = 1.2
            elif not p:
                value = 0.6
            else:
                value = 0.8
    elif text.startswith('(') and not text.startswith('()'):
        tail = text[1:]
        if tail.isspace():
            value = 0.77
            if token != text:
                value = 0.8 + 0.33 * separated_open(previous)
        elif tail.startswith(('{', '[')):
            value = 0.12
        elif tail.isalpha():
            value = 1.0
            if len(tail) > 1:
                value = min(1.7, 1.30 + 0.035 * len(tail))
        elif tail[:1] in {'"', "'"}:
            value = 0.8
        elif tail[:1] == '-':
            value = 1.48 if token != text else 0.98
        elif tail[:1] == '!':
            value = 1.35 if token != text else 1.06
        elif tail[:1] == '$':
            value = 1.2
        elif tail[:1] in {'\\', '&', '_'}:
            value = 0.95
        else:
            value = 0.70
    elif text.startswith('[') and not text.startswith('[]'):
        value = 0.06
        if token != text:
            value = 0.05 + 0.30 * separated_open(previous)
    elif token == '*(':
        value = 0.36
    elif text == 'self':
        value = 0.33 if token != text else 0.15
    return (document, token), float(value)

programs.luna:
"""Use sparse entity-word cues, plus a small domain and Chinese-token cue."""

READS = ()

# Common heads of organizations, schools, governments, and legal titles.
ENTITY_WORDS = frozenset({
    "college", "university", "institute", "corps", "council", "fund",
    "act", "union", "office", "commission", "bank", "club", "journal",
    "tournament", "center", "centre", "group", "team", "league",
    "company", "corporation", "association", "associations", "subsidiary",
    "guidelines", "regulations", "curriculum", "report", "project",
})

# A few lower-case words that modify an entity head in recurring phrases.
ENTITY_MODIFIERS = frozenset({
    "university", "national", "work", "big", "court", "research",
})


def is_name_word(text):
    text = text.strip().strip(".,:;()[]{}\"'")
    return bool(text) and (text.isupper() or text.istitle())


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    folded = word.casefold()
    has_previous = (
        prefix.position > 0
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    previous = prefix.token_strings[-2] if has_previous else ""

    # Domains and a few Chinese institution, government, and finance terms.
    if folded in {".com", "有限公司", "统计局", "指数", "黨"}:
        return None, -1.0

    if folded in ENTITY_WORDS:
        if word.istitle() or is_name_word(previous):
            return None, -1.0
        if previous.strip().casefold() in ENTITY_MODIFIERS:
            return None, -1.0

    # A blank token immediately after the end-of-thought marker.
    if word == "" and has_previous and previous == "</think>":
        return None, -0.22
    return None, 0.0

programs.sol:
"""Sparse lexical contrasts, especially in Chinese.

Predict negative contributions for selected sound/movement words, repetition,
and visible expressions; positive ones for selected qualities and the ends of
compounds such as 对白, 对华 and 探花. A fading sensory-description cue adds a
small negative bias to nearby Chinese tokens. English possibility, comparison,
several common constructions, and explicit phase markers get smaller rules.
These are partial patterns, not a reconstruction of all token-specific variation.
Signs denote contribution direction, not sentiment. State resets per document.
"""
import math

READS = ()

SOUND = set('啪砰嚓噼嗡咚嘭响聲声轰')
MOTION = set('跳蹦舞荡溅腾睁眨')
VISUAL = set('亮闪閃影俊玲莹')
EXPRESSIONS = set(('神情 神色 笑容 姿态 姿势 不禁 顿时 忽然 '
                   '形象 灵活 小心翼翼').split())
REPETITION = set('纷纷 茫茫 重重 闪闪 阵阵 洋洋 层层 狠狠'.split())
EVENTS = set('发出 声响 一声 一阵 不动 动人'.split())
CLASSIFIERS = set('个颗棵朵张根丝缕阵声')
QUALITIES = set('热熱冰冷暖新老古强強弱烈狂猛')
SENSORY_CUES = (SOUND | MOTION | EXPRESSIONS | REPETITION |
                set('欢快 兴奋 微风 眼睛 摇曳 脚步'.split()))

# Selected English lexical classes; not universal rules for their meanings.
ENGLISH = (
    (0.11, {'another'}),                           # alternative determiner
    (0.034, {'other', 'else'}),
    (0.043, {'each'}),                            # distributive determiner
    (0.074, {'last'}),
    (0.023, set('first next previous present'.split())),
    (-0.044, {'like', 'than'}),                    # comparisons
    (0.046, {'could'}),
    (-0.067, {'does'}),
    (0.055, set('possible likely probably expected maybe perhaps'.split())),
    (0.10, set('easily almost highly'.split())),    # ease/degree adverbs
    (-0.063, set('always enough everything anything'.split())),
    (0.050, set('see seen know knowledge'.split())),
    (-0.020, set('this these those their its'.split())),
    (-0.28, set('graceful solemn majestic glitter'.split())),
    (-0.10, set('dance danced laughing sparkling'.split())),
)
RELATION_HEADS = set(('type kind species force concept level result group '
                     'country university part one all instead think thought course').split())
INFINITIVE_HEADS = set('have has had is was likely expected continue'.split())
PHASES = {'<think>': 0.08, '</think>': 0.10,
          '<tool_call>': -0.108, '</tool_response>': 0.065}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, previous, description = '', '', 0.0
    else:
        _, tail, previous, description = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if token.startswith(' ') and word.isascii() and word.isalpha():
        if token == token.lower() or word in ('another', 'maybe', 'perhaps'):
            for amount, words in ENGLISH:
                if word in words:
                    value = amount
                    break
        if word == 'of' and previous in RELATION_HEADS:
            value = -0.075
        elif word == 'to' and previous in INFINITIVE_HEADS:
            value = -0.060
        elif word == 'be' and previous in ('can', 'could', 'will', 'would'):
            value = -0.035
        elif (previous, word) == ('for', 'example'):
            value = 0.065
        elif (previous, word) == ('in', 'between'):
            value = 0.13
        elif (previous, word) == ('at', 'all'):
            value = -0.105
    elif token in ("'s", '’s') and previous in ('let', 'here'):
        value = 0.075

    for amount, words in (
        (-0.22, SOUND), (-0.25, MOTION), (-0.18, VISUAL),
        (-0.35, EVENTS), (-0.25, EXPRESSIONS), (-0.27, REPETITION),
        (0.08, QUALITIES), (0.11, set('明白华華美非客')),
    ):
        if token in words:
            value = amount
            break
    if token == '跳':
        value = -0.38
    elif token == '一个个':
        value = -0.60
    elif len(token) == 2 and token[0] == '一' and token[1] in CLASSIFIERS:
        if token not in EVENTS:
            value = -0.16
    elif token in set('个颗棵丝缕一'):
        value = -0.09
    elif token == '着':
        value = -0.12
    elif token == '的':
        value = -0.022
    elif token in set('慢缓緩速'):
        value = 0.14

    # Score the completing character only, not a whole fused compound token.
    if len(token) == 1 and tail:
        last = tail[-1]
        if token in '华華美非俄朝' and last in '对對访訪驻駐赴援':
            value = 0.65
        elif (last, token) in (('对', '白'), ('访', '客')):
            value = 0.55
        elif (last, token) == ('探', '花'):
            value = 0.77
        elif token == '明' and last in '辨察查判':
            value = 0.65
        elif token in '缓緩' and last == '趋':
            value = 0.65
        elif token in '动動' and last in '飘飄跳摆擺摇搖颤顫涌扭':
            value = -0.45
        elif token == '儿' and last in '花馅':
            value = -0.50
        elif (last, token) == ('花', '香'):
            value = -0.45
        elif token == '腾' and last in '腾热':
            value = -0.55
        elif token == '地' and tail.endswith((
            '翼翼', '纷纷', '阵', '兴奋', '欢快', '悄悄', '偷偷', '乖乖'
        )):
            value = -0.40
    if token == 'ling' and tail.endswith(('twink', 'gigg')):
        value = -0.50
    elif token == '-gay' and previous in ('anti', 'pro'):
        value = 0.54

    if token and value <= 0.0 and all('\u4e00' <= c <= '\u9fff' for c in token):
        value -= 0.055 * math.sqrt(min(1.0, description))
    description = 0.7 * description + float(token in SENSORY_CUES)
    value = PHASES.get(token, value)
    return (document, (tail + token)[-10:], word, description), float(value)

programs.haiku:
"""Possessive-marker detector (layers.0.mlp.down_proj:388).

The component goes negative on the token that marks a possessive: the 's in
"Children's" or "men's", a bare ' in "residents' oral", the particle 的 after a
Chinese noun. It is most negative after people and group nouns, milder after
names and other nouns, and close to zero or slightly positive on contractions
such as "there's", "that's", "it's", "let's".
"""

READS = ()

S_MARKERS = {"'s", "’s", "'S", "’S"}
APOSTROPHES = {"'", "’"}
PEOPLE = {"children", "child", "men", "man", "women", "woman", "people", "person",
          "residents", "customers", "veterans", "kids", "students", "patients",
          "employees", "workers", "boys", "girls", "jurors", "respondents", "members",
          "parents", "friends", "family", "wife", "husband", "mother", "father",
          "son", "daughter", "brother", "sister", "player", "driver", "writer"}
CONTRACTION_HOSTS = {"there", "that", "it", "here", "what", "let", "who", "where", "how"}
PRONOUNS = {"he", "she"}


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    tok = strs[-1]
    prev = strs[-2] if len(strs) > 1 else ""
    word = prev.strip().lower()
    if tok == "的":
        return carry, -0.9
    if tok in S_MARKERS:
        if word in CONTRACTION_HOSTS:
            return carry, 0.3
        if word in PRONOUNS:
            return carry, -0.6
        if word in PEOPLE:
            return carry, -6.0
        return carry, -1.5
    if tok in APOSTROPHES and prev.startswith(" ") and word.endswith("s"):
        return carry, -3.0
    return carry, 0.0

programs.luna:
"""Predict weak negative responses to common possessive and genitive markers."""

READS = ()

CONTRACTION_HOSTS = frozenset((
    "i", "you", "he", "she", "it", "we", "they",
    "that", "there", "what", "who", "here",
))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ""
    if len(prefix.token_ids) > 1 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    ):
        previous = prefix.token_strings[-2].strip().lower()

    if token in ("'s", "’s") and previous not in CONTRACTION_HOSTS:
        return None, -1.62
    if token in ("'", "’") and previous.endswith("s"):
        return None, -1.62
    if token == "的":
        return None, -0.9
    if token == "の":
        return None, -0.27
    return None, 0.0

programs.haiku:
"""layers.0.mlp.down_proj:389 -- the component that fires on the preposition "on".

What it does: it switches on at the word "on" (as in "turn on", "went on", "on the
other hand", "impact on", "On Wednesday"), most strongly when "On" starts a sentence.
It stays silent on "on" when "on" is the fixed second half of a verb-preposition
pair that the previous word already demands ("based on", "depend on", "focus on",
"rely on", "comment on"): there the word "on" is predictable from the word before, and
the component does not fire. Everything else gets 0.

Predicted value = typical activation (in the component's own units):
  " on" (mid-sentence)       about 1.05
  " On" / "On" (sentence-start) about 1.7
  other on-forms ("ON", "-on", "_on", ".on")  about 1.0
  bare "on" (no leading space)   about 0.2
  everything else 0 (the component's small diffuse activity is not modelled).
"""

# The word before "on" that makes the following "on" a fixed collocation (component silent).
FIXED_BEFORE_ON = {
    "based", "depend", "depends", "depending", "dependent", "focus", "focused",
    "focuses", "rely", "relies", "comment", "comments", "reliance",
}

READS = ()


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    else:
        prev = prefix.token_strings[-2]
    if tok in (" On", "On"):
        value = 1.7
    elif tok == " on":
        value = 0.0 if _word(prev) in FIXED_BEFORE_ON else 1.05
    elif tok in (" ON", "-on", "_on", ".on", "'on"):
        value = 1.0
    elif tok == "on":
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Recognize bare 'be' after a modal auxiliary or infinitival 'to'.

Different auxiliaries evoke very different strengths. Handle one intervening
negation or adverb, with a small correction for pronouns before the auxiliary.
Also recognize the requests 'let me' and 'let us'. All unhandled tokens get
zero; smaller, diffuse lexical responses remain unexplained.
"""
READS = ()

BE_AFTER = {
    'to': 0.81,
    'can': -0.03,
    'will': 1.10,
    'would': 0.86,
    'may': 0.25,
    'should': 1.23,
    'must': 1.07,
    'could': 0.21,
    'might': 0.31,
    'shall': 1.17,
    'cannot': 0.28,
    "'ll": 1.02,
    '’ll': 1.02,
    "'d": 0.61,
    '’d': 0.61,
}
NEGATIVE_STEMS = {
    'won': 'will', 'wouldn': 'would', 'shouldn': 'should',
    'couldn': 'could', 'mustn': 'must',
}
ADVERBS = {
    'also', 'only', 'still', 'always', 'then', 'easily', 'ever',
    'just', 'now', 'even', 'probably', 'never',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token not in {' be', ' me', ' us'}:
        return None, 0.0
    previous = []
    for distance in (1, 2):
        if (prefix.position >= distance and
                prefix.document_ids[-1-distance] == prefix.document_ids[-1]):
            previous.append(prefix.token_strings[-1-distance].strip())
        else:
            previous.append('')
    first, second = previous
    p, q = first.lower(), second.lower()
    if token == ' me':
        value = 1.10 if first == 'Let' else (
            0.99 if first == 'let' else 0.10)
    elif token == ' us':
        value = 0.77 if p == 'let' else -0.01
    else:
        value = BE_AFTER.get(p, 0.20)
        if p in BE_AFTER and p != 'to':
            if q in {'it', 'there'}:
                value += 0.12
            elif q in {'which', 'who', 'what'}:
                value -= 0.09
            elif q in {'that', 'this', 'they', 'he', 'she'}:
                value -= 0.04
        elif p == 'not' and q in BE_AFTER:
            value = 0.06 + 0.72 * BE_AFTER[q]
        elif p in {"'t", '’t'}:
            modal = NEGATIVE_STEMS.get(q, q)
            if modal in BE_AFTER:
                value = 0.24 + 0.63 * BE_AFTER[modal]
        elif p in ADVERBS and q in BE_AFTER:
            base = BE_AFTER[q]
            if p == 'also':
                value = 0.16 + 0.80 * base
            elif p == 'never':
                value = 0.12 + 0.52 * base
            else:
                value = 0.14 + 0.72 * base
    return None, float(value)

programs.haiku:
"""Layer-0 MLP unit 391 is a detector for the word "be" in its bare, uninflected form
(and for "me" in "Let me"). It is strongest for "be" right after an obligation or future
auxiliary (should, shall, will, must, would, 'll) or the infinitive "to"; weaker after
"not"/"also"/"n't" and the weak modals (may, might, could); absent after "can".
"me" is strong after "Let"/"let". Everything else is about zero."""
READS = ()

STRONG_BE = {"should", "shall", "will", "must", "would", "ll"}
WEAK_BE = {"not", "also", "t"}
WEAKER_BE = {"may", "might", "could", "cannot"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if cur == "be":
        if prev in STRONG_BE or prev == "to":
            return None, 1.0
        if prev in WEAK_BE:
            return None, 0.5
        if prev in WEAKER_BE:
            return None, 0.25
        return None, 0.0
    if cur == "me" and prev in {"Let", "let"}:
        return None, 1.0
    return None, 0.0

programs.sol:
"""A small multilingual lexicon for treating, handling, and awaiting.

Negative pulses mark these words and a few of their token fragments. The
Chinese character 待 and the word 对待 have exceptionally large responses.
A one-word memory extends the pulse through 'treatment of/for/with' and
'handling of', and recognizes 'medical treatment', 'be treated', and
'to treat'. Unlisted tokens receive a small negative baseline. This captures
rare strong responses, not the smaller vocabulary-wide variation.
"""
READS: tuple[str, ...] = ()

TREAT = {
    'treat': -1.22, 'treated': -1.46, 'treating': -1.12,
    'treats': -1.10, 'treatment': -1.22, 'treatments': -0.88,
    'untreated': -1.02, '-treated': -1.08,
    'reat': -0.33, 'reated': -0.75, 'reatment': -0.66,
    'reating': -0.34,
}
HANDLE = {
    'handle': -0.58, 'handled': -0.60, 'handling': -0.44,
    'handles': -0.44, 'tackle': -0.40, 'dealing': -0.36,
    'tackling': -0.41, 'tackled': -0.37,
    'deal': -0.18, 'deals': -0.17, 'dealt': -0.31,
    'dealings': -0.90, 'manageable': -0.34,
    'regard': -0.21, 'regards': -0.33, 'regarded': -0.41,
    'respectful': -0.36, 'entertain': -0.36, 'entertainment': -0.56,
}
WAIT = {
    'pending': -0.58, 'awaiting': -0.56, 'awaits': -0.42,
    'waited': -0.27, 'waits': -0.31, 'waiter': -0.31,
    'waitress': -0.75, 'overdue': -0.55,
}
# Translations or translation stems of 'treat/treatment/handling'.
TRANSLATIONS = {
    'behand': -1.15, 'traitement': -0.71, 'tratamiento': -0.58,
    'tratt': -0.64, 'xử': -0.73,
    'леч': -0.50, 'лечения': -0.37, 'лечение': -0.36,
    'علاج': -0.87, '처리': -0.77,
}
EAST_ASIAN = {
    '待': -5.40, '对待': -5.97, '看待': -2.63, '有待': -3.00,
    '待遇': -1.95, '接待': -1.10, '招待': -1.42, '虐待': -0.54,
    '等待': -0.80, '期待': -0.42, '待ち': -0.65, '呆': -1.57,
    '处理': -0.83, '處理': -0.88, '治疗': -0.65, '治療': -0.46,
    '治疗方法': -0.61, '诊疗': -0.44, '治': -0.37, '搞定': -0.79,
    '相处': -1.50, '侍': -1.18, '对付': -0.71, '尊重': -0.59,
}


LEXICON = {**TREAT, **HANDLE, **WAIT, **TRANSLATIONS, **EAST_ASIAN}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    value = LEXICON.get(word, -0.003)

    if word in {'handle', 'handled', 'handles', 'handling'}:
        if not raw.startswith(' '):
            value *= 0.6
        elif token[0].isupper() and word != 'handling':
            value *= 0.66
    if word == 'treatment' and token[0].isupper() and raw.startswith(' '):
        value = -1.34

    if word == 'treatment' and previous == 'medical':
        value = -1.56
    if word == 'treated' and previous == 'be':
        value = -1.57
    if word == 'treat' and previous == 'to':
        value = -1.30

    if previous in {'treatment', 'treatments', 'reatment'}:
        if word == 'of':
            value = -0.60
        elif word == 'for':
            value = -0.41
        elif word == 'with':
            value = -0.09
    elif previous == 'treated' and word == 'with':
        value = -0.10
    elif previous == 'handling' and word == 'of':
        value = -0.29
    return (doc, word), float(value)

"""An ordinal/order-form detector, strongest on third and later positions.

English ordinal words and numeric endings such as 23rd are the main
signals. Articles and possessives modify their strength. Ordinal-shaped
spelling fragments can respond even inside unrelated words. Smaller
rules cover Chinese/Korean ordinals, numeral-plus-date/count expressions,
fractional plurals and relative order (nth/latter). The word 'seconds'
is weakly negative; unmatched tokens are zero. Carry remembers the
previous token and Chinese-number continuation, resetting per document.
"""
READS = ()
ORDINALS = {
    'first': 0.16, 'second': 1.6, 'third': 4.5, 'fourth': 5.6,
    'fifth': 6.9, 'sixth': 6.3, 'seventh': 7.0, 'eighth': 6.4,
    'ninth': 7.2, 'tenth': 4.2, 'eleventh': 7.0, 'twelfth': 7.0,
    'thirteenth': 7.0, 'fourteenth': 7.0, 'fifteenth': 7.0,
    'sixteenth': 7.0, 'seventeenth': 7.0, 'eighteenth': 7.0,
    'nineteenth': 5.4, 'twentieth': 4.3, 'thirtieth': 6.0,
    'fortieth': 6.0, 'fiftieth': 6.0, 'sixtieth': 6.0,
    'seventieth': 6.0, 'eightieth': 6.0, 'ninetieth': 6.0,
    'hundredth': 5.0, 'thousandth': 5.0, 'millionth': 6.0,
}
# Recognizable final pieces of ordinal spellings, not token IDs.
ORDINAL_PIECES = {
    'venth': 7.4, 'elfth': 6.7, 'eenth': 7.0, 'teenth': 7.4,
    'entieth': 6.5, 'ifth': 6.6, 'enth': 4.0, 'ird': 1.4,
    'inth': 2.5, 'ighth': 3.0,
}
SUFFIXES = {'st': 5.1, 'nd': 7.15, 'rd': 7.0, 'th': 7.35}
BARE_SUFFIXES = {'st': 0.25, 'nd': 1.1, 'rd': 1.5, 'th': 0.9}
SPACED_SUFFIXES = {'st': 0.5, 'nd': 0.77, 'rd': 1.0, 'th': 0.9}
COUNTERS = {
    '日': 1.55, '月': 0.82, '年': 0.66, '岁': 0.8,
    '个': 1.2, '個': 0.65, '次': 0.7, '回': 0.5,
    '号': 1.2, '號': 1.2, '일': 1.0, '월': 1.0,
    '条': 0.95, '名': 0.8, '章': 0.6, '年度': 0.8,
    '周年': 0.85, '世纪': 0.8,
}
CHINESE_NUMERALS = '一二三四五六七八九十百千两兩〇零'
POSSESSIVES = {'his', 'her', 'its', 'their', 'our', 'my', 'your', "'s", '’s'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new = carry is None or carry[0] != doc
    _, previous, order = (doc, '', False) if new else carry
    token = prefix.token_strings[-1]
    s = token.strip()
    lower, prev = s.lower(), previous.strip().lower()
    digit = bool(previous) and previous[-1].isdigit()
    numeral = digit or bool(previous and previous[-1] in CHINESE_NUMERALS)
    number = bool(s) and all(c.isdigit() or c in CHINESE_NUMERALS for c in s)
    order = number and (order or previous.strip().endswith('第'))
    joined = prev + lower if token == s and s.isalpha() else ''
    word = lower if lower in ORDINALS else joined
    value = 0.0

    if lower in ORDINAL_PIECES and token == s:
        value = ORDINAL_PIECES[lower]
    elif word in ORDINALS:
        value = ORDINALS[word]
        if lower == 'eth':
            value = 1.4
        elif lower in ORDINALS and not token.startswith(' ') and value > 3:
            value -= 0.5
        if prev == 'the':
            value += 0.55 if word == 'first' else 0.95
        elif prev in POSSESSIVES:
            value += 0.16 if word == 'first' else 0.4
        elif prev in ('a', 'an'):
            value -= {'first': 0.2, 'second': 0.6}.get(word, 1.0)
        elif prev == 'per' and word == 'second':
            value = 0.45
        if token.startswith('-'):
            if word == 'first' and prev.endswith('ty'):
                value = 3.6
            else:
                value *= 0.5
    elif lower in SUFFIXES:
        if digit:
            value = SUFFIXES[lower]
            if lower == 'th':
                if previous[-1] in '123':
                    value += 0.65
                elif previous[-1] == '0':
                    value -= 0.45
            elif lower == 'nd' and previous[-1] != '2':
                value = 4.6
            if s != lower:
                value *= 0.46 if s.isupper() else 0.2
            if token.startswith(' '):
                value *= 0.4
        else:
            base = SPACED_SUFFIXES if token.startswith(' ') else BARE_SUFFIXES
            value = base[lower]
            if s != lower:
                value *= 0.5 if token.startswith(' ') else 1.0
                if s.istitle() and not token.startswith(' '):
                    value = 0.1
            elif new:
                value = SUFFIXES[lower] * (0.4 if lower == 'st' else 0.65)
    elif lower == 'ly' and prev in ORDINALS:
        value = 0.35 * ORDINALS[prev]
    elif lower == 'ths':
        value = 4.4 if digit else 0.5
    elif lower.endswith('s') and lower[:-1] in ORDINALS and lower != 'seconds':
        value = 1.5
    elif order:
        value = 2.5 if s.isdigit() else 3.0
    elif s.startswith('第'):
        chinese_ranks = dict(zip(
            '一二三四五六七八九十',
            (0.65, 1.7, 2.8, 4.0, 4.3, 4.4, 4.2, 4.0, 4.8, 3.8),
        ))
        value = chinese_ranks.get(s[1:2], 1.1)
        if s.endswith(('次', '个', '個', '届')):
            value += 0.8
        if s == '第三方':
            value = 1.8
    elif s in COUNTERS and numeral:
        value = COUNTERS[s]
    elif lower == 'times' and numeral:
        value = 0.73
    elif lower == 'time' and prev in ORDINALS:
        value = min(1.1, 0.3 * ORDINALS[prev])
    else:
        value = {'째': 1.6, '번째': 4.2, 'nth': 1.6, 'latter': 0.6,
                 'seconds': -0.35, '-th': 1.5}.get(s, 0.0)
    return (doc, token, order), float(value)

"""Respond negatively to I and it, especially capital I at a word boundary.

These rules approximate the dominant training-data responses, not the
model's arithmetic. Capital I is weaker inside an uppercase word or after
question/condition words, and stronger at sentence/document starts. The
early-document boost fades with token position. It/it and lowercase i are
weaker; some other first-person forms are weakly negative. The first bare
or space-prefixed I gets a small extra boost. Selected plural pronouns and
possessives are weakly positive. Everything else is zero. State resets at
document boundaries.
"""
import math

READS = ()
QUESTION_WORDS = {'what', 'when', 'where', 'how', 'whether', 'who',
                  'whatever', 'whenever', 'wherever'}
CONDITION_TIME = {'if', 'before', 'after', 'until', 'than', 'once'}
MODALS = {'can', 'could', 'would', 'should', 'may', 'might', 'must',
          'shall', 'will', 'do', 'did', 'am', 'have', 'had'}
CLAUSE_LINKERS = {'that', 'as', 'which', 'because', 'since', 'though',
                  'while', 'unless', 'although'}
THINKING = {'think', 'thought', 'know', 'knew', 'believe', 'realize',
            'realized', 'feel', 'felt', 'guess', 'suppose', 'wish'}


def i_after(previous):
    word = previous.strip().lower()
    if word in QUESTION_WORDS or word in CONDITION_TIME:
        return -0.85
    if word in MODALS:
        return -0.45
    if word in CLAUSE_LINKERS:
        return -1.3
    if word in {'and', 'or'}:
        return -1.5
    if word in {'but', 'so', 'yet'}:
        return -1.9
    if word in {'maybe', 'perhaps'} or word in THINKING:
        return -1.25
    if any(c in previous for c in '.!?\n'):
        return -2.3
    if ',' in previous:
        return -2.05
    if previous and previous[-1].isalpha():
        return -1.65
    return -2.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, seen_i = 0, '', False
    else:
        position, previous, seen_i = carry[1] + 1, carry[2], carry[3]
    token = prefix.token_strings[-1]
    early = 1.0 / math.sqrt(position + 1)
    if token == ' I':
        if position == 0:
            value = -4.27
        elif previous.strip().isupper() and len(previous.strip()) == 1:
            value = -0.7 - 1.0*early
        else:
            value = i_after(previous) - 2.2*early
    elif token == 'I':
        if position == 0:
            value = -5.75
        elif previous and previous[-1].isalpha():
            value = -0.2 if previous[-1].isupper() else -2.0
        elif previous and previous[-1].isdigit():
            value = -1.8
        elif previous.rstrip().endswith(('$', '{', ';')):
            value = -2.0
        else:
            value = -2.65 - 1.5*early
    elif token == ' it':
        value = -0.97
    elif token == 'it':
        attached_to_word = previous and previous[-1].isalnum()
        value = -0.15 if attached_to_word else -0.97
    elif token in (' It', 'It'):
        value = -1.25 - 0.8*early if position else -1.19
    elif token == ' i':
        value = -0.25 - 0.5*early
    elif token in (' IT', '_IT'):
        value = -0.8
    elif token.endswith('it') and token[:-2] and all(
            not c.isalnum() for c in token[:-2]):
        value = -1.2
    elif token.endswith('It') and token[:-2] and all(
            not c.isalnum() for c in token[:-2]):
        value = -0.9
    elif token.endswith('I') and token[:-1] and all(
            not c.isalnum() for c in token[:-1]):
        if any(c in token for c in '"“('):
            value = -2.45 - 1.5*early
        elif token.startswith('.'):
            value = -1.2
        else:
            value = -1.8
    # Exact first-person forms: German/Scandinavian, Russian, Chinese.
    elif token in (' ich', ' jeg'):
        value = -0.8
    elif token in ('Ich', ' Ich'):
        value = -1.25
    elif token in (' я', 'Я', ' Я'):
        value = -0.6
    elif token in ('我', '本人'):
        value = -0.76
    elif token in (' we', ' they'):
        value = 0.085
    elif token in (' my', ' their'):
        value = 0.11
    else:
        value = 0.0
    if token in ('I', ' I'):
        if position:
            value += 0.04 if seen_i else -0.15
        seen_i = True
    return (doc, position, token, seen_i), float(value)

programs.haiku:
"""Layer-0 MLP neuron 395 (down_proj): a negative "subject pronoun" detector.

It is strongly negative on the English first-person pronoun "I" and moderately negative
on the neuter pronoun "it". Its response depends on the token's spelling:

  - "I" as a capital letter, with or without a leading space, or inside an opening
    quote or bracket: about -2 to -2.7 (bare "I" and quoted "I" are the strongest).
  - " I" after a space: about -1.9.
  - " it" (lowercase, after a space): about -1.0.
  - " It" and "It" (capitalised): about -1.3.
  - lowercase "i" and "it" without a space: small, about -0.3.
  - every other token: about 0.

The program is a lookup on the current token only; it keeps no state.
"""

READS = ()

I_BARE = {"I"}
I_SPACE = {" I"}
I_QUOTED = {'"I', "“I", "(I", "-I", ":I"}
IT_LOWER = {" it"}
IT_CAP = {" It", "It"}
LOWER_I_IT = {" i", "it"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in I_BARE:
        return carry, -2.5
    if tok in I_SPACE:
        return carry, -1.9
    if tok in I_QUOTED:
        return carry, -2.7
    if tok in IT_LOWER:
        return carry, -1.0
    if tok in IT_CAP:
        return carry, -1.3
    if tok in LOWER_I_IT:
        return carry, -0.3
    return carry, 0.0

programs.luna:
"""A small detector for the pronoun-like tokens that dominate this component's
large responses. Ordinary tokens receive zero; first-person I receives a larger
negative value than it/It, with a smaller response for lowercase i.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " I":
        value = -2.29
    elif token == "I":
        value = -2.93
    elif token in (" It", "It"):
        value = -1.32
    elif token in (" it", "it"):
        value = -1.04
    elif token in (" i", "i"):
        value = -0.65
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""An orthographic vowel/consonant boundary detector for short continuations.

Chunks beginning with y, j, v, w, Cyrillic в, or iotated vowels usually
respond positively after consonants and negatively after vowels.  The next
letter distinguishes a glide followed by a vowel from one followed by a
consonant.  Longer chunks, consonant family and case moderate this response.
Ordinary Latin vowel-initial chunks instead respond to adjacent vowels; three
short Russian inflectional endings get an extra response.  The coefficients
approximate training averages using letters and suffix forms, not token IDs.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouıæœøɔɑɒɐɜɞɪʊʌəɨʉɯɤɶɵɘɛʏ'
             'аеёиоуыэюяіїєѣъαεηιουω')
RUSSIAN_INFLECTIONAL_ENDINGS = {'ет', 'ем', 'ев'}
VOWELS_WITH_Y = VOWELS | {'y'}
# Amplitudes after consonants and vowels, respectively.
ONSET = {
    'y': (0.67, -1.03),
    'j': (0.88, -0.35),
    'v': (0.64, -0.41),
    'w': (0.51, -0.50),
    'в': (1.09, -0.54),
    'я': (1.21, -0.81),
    'ю': (1.69, -0.45),
    'е': (0.09, -0.27),
    'ё': (0.53, -0.63),
}


def letter(c):
    if not c:
        return ''
    if 'CYRILLIC' in unicodedata.name(c, ''):
        return c.lower()  # й is not the vowel и
    return unicodedata.normalize('NFD', c.lower())[0]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, text)
    if not text or not prev or not text.isalpha():
        return carry, 0.0
    first, last = text[0].lower(), letter(prev[-1])
    n = min(len(text), 6) - 1
    if first in ONSET:
        pos, neg = ONSET[first]
        if len(text) > 1:
            if first in 'yjvw':
                if letter(text[1]) in VOWELS:
                    pos *= 1.7 if first == 'y' else 0.9
                    neg *= 0.45 if first == 'y' else 0.7
                else:
                    pos *= 0.4
                    neg *= 1.7 if first == 'y' else 0.8
            else:
                pos *= 0.3 if first in 'яё' else 0.5
                neg *= 0.8 if first == 'е' else 0.5
        # Common short Russian inflectional endings are more responsive
        # than other continuations beginning with е.
        if text.lower() in RUSSIAN_INFLECTIONAL_ENDINGS:
            pos, neg = 0.60, -0.90
        if last in VOWELS or last == 'y':
            factor = 0.02 if last == 'y' else 0.84 if last in 'eеэєѣ' else 1.0
            if last in 'aаαuуυ':
                factor *= 1.18
            elif last in 'iıиіїы':
                factor *= 0.82
            decay = (1.0, 1.1, 1.0, 0.8, 0.7, 0.4)[n]
            return carry, float(neg * factor * decay)
        if last.isalpha() and any(s in unicodedata.name(last, '')
                                  for s in ('LATIN', 'CYRILLIC', 'GREEK')):
            factor = 1.5 if last in 'kghкгх' else 0.53 if last in 'nн' else 1.0
            if last in 'rlрл':
                factor = 0.75
            elif last in 'ьй':
                factor = 0.50
            if text[0].isupper() != prev[-1].isupper():
                factor *= 0.82
            if len(prev.strip()) == 1:
                factor *= 1.29
            if len(prev) > 1 and letter(prev[-2]) in VOWELS:
                factor *= 1.12
            decay = (1.0, 1.2, 1.0, 0.53, 0.28, 0.17)[n]
            return carry, float(pos * factor * decay)
        return carry, -0.27 if first == 'y' and len(text) == 1 else 0.0
    if first in 'aeiou' and last in VOWELS_WITH_Y:
        gain = {'a': 0.40, 'e': 0.20, 'i': 0.02, 'o': 0.12, 'u': 0.07}[first]
        gain *= (0.25 if last == 'e' else 1.8 if last == 'o' else
                 2.2 if last == 'u' else 1.2 if last == 'a' else 1.0)
        if first == 'e':
            gain = (0.65 if last == 'a' else 0.35 if last == 'o' else
                    0.15 if last == 'y' else 0.07 if last == 'u' else 0.02)
        if len(text) > 1:
            if letter(text[1]) in VOWELS:
                gain *= 0.15
            elif text[1].lower() == 'm':
                gain *= 1.5
        return carry, float(gain * (1.0, 1.0, 0.8, 0.45, 0.16, 0.08)[n])
    return carry, 0.0

programs.haiku:
"""Glide after a letter, inside a word (variant E: cell values).

Fires on a word-internal piece that opens with a glide-like letter: y, j, v, w, Cyrillic в, я, ю, ё.
Sign follows the letter before the piece:
- after a consonant it is positive (a glide that opens a syllable, e.g. "g|ye", "k|jo");
- after a vowel it is negative (a glide that follows a vowel, e.g. "Vo|yn", "A|ys"), strongest for y.
Size: y-pieces are largest when a vowel follows the y (ye, ya, yo), weaker when a
consonant follows (yn, ys). Other pieces (word starts, digits, punctuation) predict 0.
"""
READS = ()

VOWELS = set("aeiouäöüéèàâîôûæøåаеёиоуыэюя")
GLIDES = set("yjvwвюяё")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    word = cur.strip()
    if cur[:1] == " " or not word.isalpha() or prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    first = word[0].lower()
    prev = prefix.token_strings[-2].strip()[-1:].lower()
    if prev in VOWELS:
        if first == "y":
            if len(word) == 1:
                return None, -1.0
            return None, -0.5 if word[1].lower() in VOWELS else -1.6
        if first in GLIDES:
            return None, -0.3
        if first in "ae":
            return None, 0.2
        return None, 0.0
    if prev.isalpha() and first in GLIDES:
        if first == "y":
            if len(word) == 1:
                return None, 0.7
            return None, 1.1 if word[1].lower() in VOWELS else 0.2
        return None, 0.5
    return None, 0.0

programs.sol:
"""Approximate a local 'focused one / singular unit' response.

Strong examples are only/each one, ordered counts, and signed 1.
Other small counts and counted units respond less; the number-word
response decreases approximately with the size of the count. Ordinary references
are weaker, and 'loved one(s)' is negative. Analogous rules recognize
Chinese 一 and a few translations of one. Brackets and identifier spellings
are allowed, but ordinary word suffixes are not counted as number words.
Only two preceding tokens are retained, resetting between documents.
Small responses on unrelated words are deliberately omitted.
"""
READS = ()

CARDINALS = {
    'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
    'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
}
ORDINALS = {'first', 'second', 'third', 'fourth', 'fifth', 'next'}
UNITS = {'line', 'digit', 'hand', 'day', 'side', 'step', 'solution',
         'character', 'letter', 'half', 'way', 'value'}
ONE_TRANSLATIONS = {'één', 'uno', 'один', 'одна', 'одно', 'одного',
                    'одной', 'одну'}
# Calibrated grammatical cues, reused across number words and counted units.
CUES = (
    (2.6, {'only', 'single', 'plus'}),             # exclusive / additive
    (2.5, {'each'}),                            # individuating
    (1.9, ORDINALS | {'every', 'which', 'another', 'just'}),
    (1.6, {'least', 'last'}),                    # bounds / ordering
    (1.4, {'than', 'but', 'by'}),                # contrast / distribution
    (1.1, {'no', 'any', 'number', 'exactly', 'either', 'other', 'same', 'final'}),
    (0.8, {'that', 'this', 'and', 'or', 'on', 'also', 'after', 'so'}),
    (-0.25, {'the', 'from', 'my', 'your', 'our', 'his', 'her', 'their', 'its'}),
    (0.2, {'of', 'in', 'at', 'as', 'into', 'about'}),
    (-0.05, {'be', 'are', 'were'}),
    (0.55, {'is'}),
    (1.0, {'then'}),
)


def focus(word):
    for strength, words in CUES:
        if word in words:
            return strength
    return 0.4


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    old, older = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    word, previous = token.strip().lower(), old.strip().lower()
    name = word.lstrip('-_([{\"\'')
    boundary = token[:1].isspace() or token[:1].isupper() or not old
    boundary = boundary or not old[-1:].isalpha() or name != word
    value = 0.0

    if len(word) == 1 and word.isdecimal():
        digit = int(word)
        sign = previous.endswith(('-', '−', '–', '+', '±'))
        value = 0.0 if previous.isdecimal() else -0.015
        if digit == 1:
            value = 0.025 if word == '1' else 0.15
            if not old:
                value = -0.075
            elif sign:
                value = 0.7 if old[:1].isspace() else 0.55
                if previous.endswith('+'):
                    value = 0.7
                if '(' in previous:
                    value = 0.87
                elif any(c in previous for c in '=<>'):
                    value = 0.8
            elif old.isspace():
                earlier = older.strip().lower()
                value = 0.045 + 0.2 * (focus(earlier) - 0.4)
                if earlier.endswith(('-', '−', '–', '+', '±')):
                    value = 0.5 if earlier.endswith(('+', '−', '±')) else 0.35
            elif previous.isdecimal():
                value = 0.07 if previous.endswith('1') else -0.04
            elif previous.endswith('['):
                value = -0.15
            elif previous.endswith('('):
                value = -0.025
            elif previous.endswith(('×', '*', '⋅', '·')):
                value = 0.2
        elif sign and digit:
            value = 0.2 if digit <= 3 else 0.1
    elif boundary and (name in CARDINALS or name in UNITS
                      or name in {'once', 'single', 'another', 'ones'}):
        strength = focus(previous)
        cue = strength - 0.4
        if name == 'one':
            value = strength if old else 2.2
            if name != word:
                value += 0.3
            if previous in {'other', 'same'}:
                value = 0.8
        elif name in CARDINALS:
            count = CARDINALS[name]
            value = 0.03 + cue / count
            if previous in ORDINALS:
                value = 0.1 + 2.2 / count
            elif previous == 'last':
                value = 0.1 + 1.7 / count
            elif previous in {'each', 'every'}:
                value = 0.1 + 2.0 / count
            if not old:
                value = 0.7 / (count - 1) ** 0.5
        elif name in UNITS:
            cue = 1.7 if previous == 'one' else cue
            value = (0.5 if name == 'line' else 0.2) * cue
            if name == 'digit':
                value += 0.18
        else:
            base = 0.2 if name == 'once' else 0.1 if name == 'single' else 0.0
            value = base + 0.5 * cue
        if name in {'one', 'ones'} and previous == 'loved':
            value = -0.7
    elif token.endswith('One') and len(token) > 3:  # camel-case identifier
        value = 0.5
    elif word in ONE_TRANSLATIONS and boundary:
        value = 0.4
    elif word.startswith('一'):
        value = 0.2
        if previous in {'每', '各', '哪', '何'}:     # each / every / which
            value = 2.5
        elif previous in {'同', '某', '另', '任'}:  # same / some / other / any
            value = 1.4
        elif previous.endswith(('只有', '仅有', '僅有', '只剩')):  # only
            value = 1.6
        elif previous in {'这', '這', '那', '下', '前', '第'}:
            value = 1.0                           # demonstratives / order
        elif previous in {'在', '从', '從', '是', '做', '写', '寫'}:
            value = -0.2                          # locative / action cues
    elif '一' in word:
        # Grammatical particle prefixes are less focused than bare one.
        value = -0.3 if word.startswith(('了', '是', '在', '的')) else 0.1
    return (doc, token, old), float(value)

"""Approximate consonant-to-consonant subword joins and conversation markup.

Training peaks often occur where a short consonant-starting fragment follows
another fragment's consonant ending. The rule uses Latin/Cyrillic spelling
classes, after lowercasing and removing diacritics. Vowel-bearing previous
fragments with several final consonants give larger responses, especially
before labial letters. Length, case and repeated boundary letters refine this.
Dialogue delimiters and the assistant token have separate fitted responses.
Only the previous token is retained; document changes clear that context.
This is a spelling approximation, not an exact phonological or lexical model.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюя')
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxzбвгджзклмнпрстфхцчшщ')
LABIALS = frozenset('bmpfvбмпфв')
LIQUIDS = frozenset('lrлр')
ALVEOLARS = frozenset('tdszтдсз')
FRICATIVES = frozenset('fsvzhфсвзшжх')
CONSONANT_GROUPS = ('ch', 'sh', 'th', 'ph', 'wh', 'sch', 'ng', 'ck')
MARKUP = {
    '<tool_call>': 1.0775,
    '</tool_call>': 0.7362,
    '<tool_response>': 0.6406,
    '</tool_response>': 0.3556,
    '<|im_start|>': 0.3258,
    '<|im_end|>': -0.0549,
    '<think>': 0.3285,
    '</think>': 0.0644,
    'assistant': -0.5419,
}


def fold(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def continuation(token, previous):
    s = fold(token)
    p = fold(previous)
    if not s or s[0] not in CONSONANTS:
        return -0.0090 if s and s[0] in VOWELS else -0.0015
    trailing = 0
    for c in reversed(p):
        if c not in CONSONANTS:
            break
        trailing += 1
    if trailing == 0:
        return -0.0066
    if len(token) > 3:
        return 0.0319
    if not any(c in VOWELS for c in p):
        if p.endswith(CONSONANT_GROUPS):
            return 0.2983
        return 0.0897 if sum(c in CONSONANTS for c in s) <= 1 else 0.0098
    if trailing == 1:
        if not any(c in VOWELS for c in s):
            return 0.2224
        return 0.0388 if p[-1] == s[0] else 0.1345
    if s[0] in LABIALS:
        if p[-1] in FRICATIVES:
            return 0.2851
        return 1.0176 if p[-1] in ALVEOLARS else 0.5114
    if s[0] in LIQUIDS:
        return 0.1154
    if token[0].isupper():
        return 0.0993
    return 0.2364 if s[0] in ALVEOLARS else 0.4205


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != document
    previous = '' if fresh else carry[1]
    token = prefix.token_strings[-1]
    if token in MARKUP:
        value = MARKUP[token]
        if fresh and token == '<|im_start|>':
            value = -0.0335
        elif fresh and token == 'assistant':
            value = -0.2424
        elif fresh and token == '<tool_call>':
            value = 0.4413
    else:
        value = continuation(token, previous)
    return (document, token), float(value)

