    "ultimately", "honestly", "frankly", "still", "还", "也", "很", "非常", "还是", "已经",
}
READS = ()
GROUPS = [(HEDGE, 0.9), (REVEAL, 1.35), (ASK, 1.2), (TIME, 0.95), (FILLER, 0.86), (WEAK, 0.4)]


