"""Negation detector: fires on the word or symbol that negates a verb phrase.

Examples: n't in "don't", "can't", "isn't"; "not" in "do not", "may not", "is not";
"cannot"; Chinese 不 / 不能; and the logical-not "!" / "(!" in code such as "if (!x)".
- n't after do/does/did or a modal (don't, can't, won't): strongest, about 2.2-2.7.
- n't after is/are/was/were (isn't, wasn't): weaker, about 1.3.
- "not" after do/does/did/a modal or "if" (do not, may not, if not): about 1.6.
- "not" after will/would/have/to (about 1.0); silent after is/are/was/were, commas, and "and"/"but".
Otherwise the program is 0.
"""

READS = ()

DO = {" do", " does", " did", " Do", " Did", " Does", " don", " doesn", " didn", " Don", " Doesn", " Didn"}
MODAL = {" can", " could", " may", " might", " should", " must", " need", " Could", " Can",
         " cannot", " if", " If", " maybe", " perhaps", " why", " won", " wouldn", " couldn",
         " shouldn", " Won", " shall", "if", " Maybe"}
MEDIUM = {" will", " would", " have", " has", " had", " to", " or", " probably", " haven",
          " hasn", " hadn"}
COPULA = {" is", " are", " was", " were", " am", " isn", " aren", " wasn", " weren", "'s",
          "’s", "'m", "’m", "'re", "’re", " Isn", " Aren"}
SILENT = {",", " and", " but", " so", " it", " they", " we", " you"}

NEG_CLITIC = ("'t", "’t", "'T")
NOT_WORDS = (" not", "not", " NOT", " Not")
CHINESE_NOT = ("不", "不能", "不会", "不要", "不用", "不需要", "无法", "不可", "不得")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    value = 0.0
    if t in NEG_CLITIC:
        if prev in COPULA:
            value = 1.3
        elif prev == " don" or prev == "don":
            value = 2.7
        else:
            value = 2.2
    elif t in NOT_WORDS:
        if prev in DO or prev in MODAL:
            value = 1.6
        elif prev in MEDIUM:
            value = 1.0
        elif prev in COPULA or prev in SILENT:
            value = 0.0
        else:
