READS = ()

QUANTIFIERS = frozenset('any some every several neither'.split())
CONCESSIONS = frozenset('though although despite yet'.split())
OBLIGATION = frozenset('must should need needs'.split())
HELP_AND_EVALUATION = frozenset('help helpful important quality meaningful'.split())
USAGE = frozenset('used uses using'.split())
CONTROL_AND_DEPENDENCE = frozenset('control depend depending'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    prev_first = False if first else carry[2]
