    w = word.lower()
    p = previous.strip().lower()
    value = -.002

    if w in QUANTIFIERS or w == 'other':
        value = .038
    elif w == 'either':
        value = .093
    elif w in CONCESSIONS:
        value = .105 if w in ('despite', 'yet') else .040
    elif w in ('all', 'both'):
        value = -.040
    elif w in OBLIGATION or w in ('might', 'cannot'):
        value = -.030
    elif w in USAGE:
        value = -.043
    elif w in CONTROL_AND_DEPENDENCE or w == 'certain':
        value = -.105
    elif w in ('high', 'higher', 'low'):
        value = -.067
    elif w in HELP_AND_EVALUATION:
        value = .095
    elif w in ('through', 'about'):
        value = .040
    elif w in ('around', 'another'):
        value = -.063
    elif w in ('because', 'however', 'therefore'):
        value = -.030
    elif w == 'could':
        value = .057
    if word in ('Can', 'Could'):
        value = 1.178 if first and s == word else .190

    # Literal conversational and document-control formats.
    if s == '<|im_start|>':
        value = -.136 if first else -.026
    elif s == '<tool_call>':
        value = -.066 if first else .087
    elif s == '\t\n':
        value = .080
    elif s and set(s) == {'·'}:
        value = .130
    elif word.startswith('#include'):
        value = -.125
    elif first and s == 'package':
        value = -.245
    elif first and s.startswith('#'):
        value = -.160 if s.startswith('##') else -.102
    elif first and w == 'the':
        value = -.075

    if p == 'how' and w in ('can', 'could'):
        value = .450 if previous.strip() == 'How' else .270
        if prev_first and previous == 'How':
            value = .600
    elif p == 'how' and w in ('do', 'does', 'did'):
        value = .190
    elif w == 'to' and p in ('unable', 'failed'):
        value = .140
    elif w == 'to' and p in ('how', 'used', 'according'):
        value = -.060
    elif w in ('a', 'an', 'the') and p in ('with', 'by'):
        value = .035 if p == 'with' else -.040
    elif word in ("'t", '’t') and p == 'can':
        value = -.120 if word == "'t" else -.180
    return (doc, s, first), float(value)

"""Respond to written backslash escapes and doubled markup punctuation.

Repeated backslashes dominate; single escapes, HTML entity openers,
double underscores, hash headings and comment leaders are weaker.
Recent escape fragments suppress single escapes.  Ordinary words are zero.
The fitted amplitudes approximate the component, not its small lexical noise.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    previous, blank = ('', True) if fresh else carry[1:]
    s, spaced = token.strip(' \t\r\n'), token.startswith(' ')
    value = 0.0
    if '\\' in s:
        run = max(len(m.group()) for m in re.finditer(r'\\+', s))
        if run > 1:
            value = 2.5 if run == 3 else (5.6 if run >= 4 else 4.95)
            if run == 2:
                if '\n' in token or s.endswith('.'):
                    value = 3.0
                elif s.startswith((':', "('")):
                    value = 5.5
                elif spaced or s.startswith('}'):
                    value = 4.4
        elif '\\"' in s or "\\'" in s:
            value = 1.1 if spaced or s.startswith('(') else 0.8
            if s.endswith('\\'):
                value = 0.9 if ',' in s else 0.1
            elif s.endswith((')', ');')):
                value = 0.25
            elif s.endswith((',', ':', '>', ']')) or s.startswith('='):
                value = 0.56
            if '\\' in previous and s == '\\"':
                value -= 0.2
        elif s.startswith('\\'):
            value = 0.52
            if s in ('\\n', '\\t'):
                value = 0.28 if s == '\\n' else -0.03
            elif s.startswith(('\\xc', '\\xe', '\\u')):
                value = 0.65
            elif s.startswith('\\x'):
                value = 0.13
            if '\\' in previous and s in ('\\', '\\n'):
                value -= 0.45 if s == '\\' else 0.28
            if '\n' in previous and s == '\\':
                value += 0.3
            if fresh and s == '\\':
                value = -0.2
        else:
            value = 0.3 if s[0] in "({\"'" else -0.18
    elif s == '__':
        value = 0.56 if spaced else 0.81
    elif '&#' in s:
        value = 1.08 if spaced else 0.87
    elif '#' in s and not any(c.isalpha() for c in s):
        value = 0.33 if not spaced else (0.2 if s != '#' else -0.02)
        if fresh:
            value = 1.27 if s == '##' else 0.04
    elif s.startswith('///'):
        value = 0.56 if spaced else 0.63
    elif s == '*' and spaced and blank:
        value = 0.6
    if '\n' in token:
        blank = not token.rsplit('\n', 1)[1].strip()
    else:
        blank = blank and not token.strip()
    return (doc, token, blank), float(value)

