r"""layers.0.mlp.down_proj:404 -- a "backslash escape" detector.

Fires on the current token when it is a backslash, or contains one, as it does in
escaped text: a string literal or JSON written inside code, or a log of escaped bytes.
Read the token alone, with no context:

- a token with two or more backslashes (an escaped backslash, `\\`) fires hardest, ~4.6;
- an escaped quote opening a token (`\"`, `\'`, ` \"`, `(\"`) fires moderately, ~0.7;
- a backslash opening any other token (`\`, ` \`, `\n`, `\x..`) fires weakly, ~0.4;
- a backslash after a letter or closing punctuation (`)\`, `.\`, `}\`) does not fire, ~0;
- the underscore token `__` and repeated-symbol tokens (`#`, `###`, `///`, ` *`) fire a little, ~0.3-0.8.

Everything else predicts 0. No state is carried between positions.
"""
import re

READS = ()

DOUBLE_BACKSLASH = re.compile(r"\\\\")          # two or more backslashes in a row
ESCAPED_QUOTE = re.compile(r"^ ?\(?\\[\"']")    # \" or \' opening the token
BACKSLASH_START = re.compile(r"^ ?[\"'(]?\\")   # backslash opening the token
UNDERSCORES = {"__", " __"}
SYMBOL_RUNS = {"#", "##", "###", " #", " ##", " ###", "*", " *", "**", " **",
               "///", " ///", "///\n", " ///\n"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if DOUBLE_BACKSLASH.search(token):
        value = 4.6
    elif ESCAPED_QUOTE.match(token):
        value = 0.7
    elif BACKSLASH_START.match(token):
        value = 0.4
    elif "\\" in token:
        value = 0.0
    elif token in UNDERSCORES:
        value = 0.8
    elif token in SYMBOL_RUNS:
        value = 0.25
    else:
        value = 0.0
    return carry, value

