CHINESE_DIRECTIONS = {
    '上': -0.3, '下': -0.13, '入': -0.47, '出': -0.28,
    '来': -0.31, '进': -0.6, '進': -0.53, '去': -0.1,
    '出来': -0.72, '出來': -1.05, '下来': -0.95, '过去': -0.94,
    '過來': -1.6, '过来': -1.66, '起来': -0.7, '回来': -1.12,
    '出去': -0.8, '开': -0.45, '開': -0.28, '起': -0.28,
}
# Weak preposition responses: (baseline, motion sensitivity, direction echo).
LINKS = {
    'in': (0.0, 0.17, 0.16), 'on': (0.04, 0.12, 0.27),
    'at': (-0.01, 0.2, 0.22), 'from': (0.05, 0.14, 0.2),
}
TRAILING = re.compile('[A-Za-z]+$')


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    match = TRAILING.search(token)
    word = '' if not match else (
        previous + token if match.start() == 0 else match.group())[-40:]
    carry = (doc, word)
    if token == '<|endoftext|>':
        return carry, 1.44
    bare = token.strip().lstrip('-')
    if bare in CHINESE_DIRECTIONS:
        return carry, CHINESE_DIRECTIONS[bare]
    key, prev = bare.lower(), previous.lower()
    value = 0.0
    if key in DIRECTIONS:
        if token[:1].isspace() or token.startswith('-'):
            scale = 1.5 if key in PARTICLES else 0.7 if key in GOALS else 1.0
            value = DIRECTIONS[key] + scale * context(prev)
        else:
            scale = 0.8 if key == 'back' else 0.25 if key == 'up' else 0.45
            value = scale * DIRECTIONS[key]
        if bare != key:
            value *= 0.65
    elif token[:1].isspace():
        if key in LINKS:
            base, motion, echo = LINKS[key]
            value = base + (echo * DIRECTIONS[prev] if prev in DIRECTIONS
                            else motion * context(prev))
        elif key in {'of', 'the', 'to', 'a', 'an'} and prev in DIRECTIONS:
            value = 0.1 * DIRECTIONS[prev]
    return carry, float(value)

programs.luna:
"""Approximate a sparse early-layer signal for document endings and motion words.

End-of-document markers are assigned a positive pulse; several common direction
and motion words receive a negative pulse. Everything else is treated as neutral.
"""

READS = ()

END_MARKERS = {"<|endoftext|>"}
STRONG_PARTICLES = {"down", "out", "up", "off", "back", "forward"}
PATH_WORDS = {"through", "around", "over", "under", "into", "toward", "towards"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in END_MARKERS:
        value = 1.4
    elif word in STRONG_PARTICLES:
        value = -1.2
    elif word in PATH_WORDS:
        value = -0.54
    else:
        value = 0.0
    return None, value

programs.sol:
"""A small union of independent lexical triggers.
'Such', double underscores and web-address 'www' are positive; assistant
labels and the end-of-thought tag are negative. Some Russian, Chinese
and Japanese 'such'-like determiners are positive too.
Classical Chinese grammatical particles also give a positive response.
These rules summarize large, repeatable training responses; smaller
word-specific responses and Chinese register effects are omitted.
Only the previous token is remembered; it resets at document boundaries.
"""
READS = ()

ARCHAIC_PARTICLES = frozenset('曰皆矣哉焉乃遂勿甚')
CHINESE_LINKERS = frozenset('之而')
CHINESE_GRAMMAR = frozenset('者令為为以其所於于若使此彼乎')
RUSSIAN_SUCH = frozenset(('такой', 'такие', 'такого', 'такая', 'такую'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ''
    else:
        _, previous = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    low = word.lower()

    if low == 'such':
        value = 1.16
        if previous.strip().lower() == 'as':
            value = 0.96
        elif s == 'Such' or word == 'SUCH':
            value = 1.28
        elif s == 'such':
            value = 1.12
        elif s == ' Such':
            value = 1.14
    elif s == '__':
        value = 0.64
    elif s.endswith('__') and '___' not in s:
        value = 0.52 if s == '/__' else 0.40
    elif s.startswith('__') and '___' not in s:
        value = 0.15 if '(' not in s else 0.0
    elif low == 'www':
        value = 0.84 if s == 'www' and previous.endswith('://') else 0.43
    elif low == 'assistant':
        value = -0.62 if s == 'assistant' else -0.28
    elif s == '</think>':
        value = -0.16
    elif low == 'таких':
        value = 0.70
    elif word in RUSSIAN_SUCH:
        value = 0.43
    elif word in ('这样的', '这种', 'そんな'):
        value = 0.28
    elif word in ARCHAIC_PARTICLES:
        value = 0.65
    elif word in CHINESE_LINKERS:
        value = 0.28
    elif word in CHINESE_GRAMMAR:
        value = 0.15
    else:
        value = 0.0

    return (doc, s), float(value)

programs.haiku:
"""Layer-0 MLP down_proj, component 406: a "such" detector.

What it does, in plain terms:
- Strongest: the English word "such" (any capitalisation: "such", "Such", "SUCH").
  This is the component's main job. It fires on "such" in "such as", "such a",
  "such that", "such costs", and writes a large positive signal there (about 1.15).
- Moderate positive (about 0.6): the Russian "such" words таких / такие / такой,
  and the double-underscore token "__" and "www", which appear in package and
  file names (e.g. "solid-primitives__1.0") and in URLs.
- Negative (about -0.6): the token "assistant", the role name in chat transcripts
  ("<|im_start|>assistant"). Only the current token is read, so no carry is needed.
- Everything else is about 0. Its small residual (many common tokens at +-0.05) is not modelled.

The values are the average activation of each group on training text.
"""

READS = ()

SUCH = {"such"}
SUCH_RUSSIAN = {"таких", "такие", "такой"}
UNDERSCORE_OR_WWW = {"__", " __", "/__", ".__", "www"}
ASSISTANT = {"assistant"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SUCH:
        value = 1.15
    elif word in SUCH_RUSSIAN or word in UNDERSCORE_OR_WWW:
        value = 0.6
    elif word in ASSISTANT:
        value = -0.6
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Surface approximation to an English noun-slot opening signal.

Articles and related noun modifiers prime a response to spaces, quotes,
number words and short fragments. Long lowercase words usually elicit
little or negative activity. A weak trace survives one intervening word;
a separate space also leaves a smaller response on the next digit.
Coefficients were fitted on training activations. Detailed word-specific
preferences are deliberately left out; there is no token-ID table.
"""
import math

READS = ()
POSSESSIVES = set('my your his her its our their'.split())
DEMONSTRATIVES = set('this that these those'.split())
QUANTIFIERS = set('some any each every another all both no'.split())
CARDINALS = set('''one two three four five six seven eight nine ten eleven
    twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen
    twenty thirty forty fifty sixty seventy eighty ninety hundred thousand
    million billion'''.split())
NOUN_MODIFIERS = set('''first second third fourth fifth sixth seventh eighth
    ninth tenth early late last next initial previous current final original
    new old big red blue green black white other same different
    additional extra full large small thin thick short long own possible
    single entire whole free top'''.split())
MONTHS = set('''january february march april may june july august september
    october november december'''.split())
ADJECTIVE_SUFFIXES = (
    'ous', 'ful', 'less', 'able', 'ible', 'ive', 'ic', 'ary', 'al', 'est',
)
ADVERB_EXCEPTIONS = set('family supply apply reply assembly italy july'.split())
INTENSIFIERS = set('''very so too quite rather much highly extremely entirely
    particularly really truly'''.split())
DEGREE = set('''more most less least only almost nearly approximately
    roughly not'''.split())


def adjective_like(token):
    w = token.strip().lower()
    return token.startswith(' ') and len(w) >= 5 and w.endswith(ADJECTIVE_SUFFIXES)


def participle_like(token):
    w = token.strip().lower()
    return token.startswith(' ') and len(w) >= 6 and w.endswith(('ed', 'ing'))


def modifier(token):
    """Return lexical gain and activation on a separate following space."""
    w = token.strip().lower()
    if w == 'the':
        return 1.0, 4.44
    if w == 'a':
        if token == ' a':
            return 0.76, 3.41
        return 0.32, (0.95 if token == 'a' else 1.51)
    if w == 'an':
        if token == ' an':
            return 0.84, 4.23
        return 0.25, 1.0
    if w in POSSESSIVES:
        return 0.65, 2.79
    if w in DEMONSTRATIVES:
        return 0.12, 0.84
    if w in QUANTIFIERS:
        return 0.31, 1.55
    if w in CARDINALS or w in NOUN_MODIFIERS:
        return 0.42, 1.70
    if adjective_like(token):
        return 0.12, 0.22
    if participle_like(token):
        return 0.05, 0.26
    if token in ("'s", '’s'):
        return 0.26, 1.24
    return 0.0, 0.0


def surface(token):
    """Response shape for everything except a standalone space."""
    w = token.strip()
    if token.isspace():
        return 0.37
    if not w:
        return 0.0
    if token.startswith(' '):
        ch = w[0]
        if ch in '$£€¥₹':
            return 3.23
        if ch in '"\'`“‘':
            if ch == '"':
                height = 3.15
            elif ch in "'`":
                height = 2.46
            else:
                height = 2.53
            # A compound token has already consumed part of the quoted item.
            return height / len(w)**1.2
        if ch in '([{\\':
            return 1.82
        if ch.isalpha():
            low = w.lower()
            if low in MONTHS:
                return 1.63
            if low.endswith('ly') and low not in ADVERB_EXCEPTIONS and len(low) >= 4:
                return 0.59
            if low in CARDINALS:
                return 1.76
            if low in INTENSIFIERS:
                return 1.70
            if low in DEGREE:
                return 0.92
            n = len(w)
            value = (-0.114 + 2.91 * math.exp(-0.75 * n)
                     + 0.34 * ch.isupper() * (1.0 - 1.0 / n))
            if n > 1 and ch.isupper():
                style = 0.36 if w[1:].islower() else 0.0
                if w.isupper():
                    style = -0.39
                value += style * math.exp(-0.3 * n)
            return value
        return 0.75
    if w[0].isdigit():
        return 1.09
    return 0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, older_gain, older_gap, position = '', 0.0, 0.0, 0
    else:
        _, previous, older_gain, older_gap, position = carry
    token = prefix.token_strings[-1]
    gain, gap = modifier(previous)
    word_trace = gap_trace = 0.0
    w = previous.strip()
    if previous.startswith(' ') and len(w) >= 3 and w.isalpha():
        word_trace, gap_trace = 0.11, 0.62
    if adjective_like(previous):
        word_trace += 0.24
        gap_trace += 0.90
    if participle_like(previous):
        word_trace += 0.08
        gap_trace += 0.52
    if token == ' ':
        value = gap + older_gain * gap_trace
    else:
        value = surface(token) * (gain + older_gain * word_trace)
    if previous == ' ' and token.isdigit():
        value += 0.38 * older_gap
    if position == 1:
        value += 0.53 * gain * (4.4 if token == ' ' else surface(token))
    return (doc, token, gain, gap, position + 1), float(value)

programs.haiku:
"""Fires on the first token of a noun phrase that follows 'the' / 'a' / 'an' (or a possessive),
when that token is a bare space, a quote or symbol, a number word, a single capital letter or
a quantity word: the spot where a number, a quoted term, a name or a code identifier is about
to start. Words like 'other', 'certain' and 'present' push slightly negative."""
READS = ()
DETS = {"the", "The", "a", "A", "an", "An", "his", "her", "their", "our", "my", "its", "every", "any", "each"}
NUMWORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"}
QUANT = {"very", "most", "more", "only", "above"}
NEGATIVE = {"other", "certain", "present"}
def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2:
        return None, 0.0
    tok = toks[-1]
    s = tok.strip()
    if toks[-2].strip() in DETS and tok == " ":
        return None, 4.0
    if len(toks) >= 3 and toks[-2] == " " and toks[-3].strip() in DETS and tok.isdigit():
        return None, 1.8
    if toks[-2].strip() not in DETS:
        return None, 0.0
    if s in NEGATIVE:
        return None, -0.7
    if s in NUMWORDS:
        return None, 1.5
    if s in QUANT:
        return None, 1.0
    if s and s[0] in "'\"`$(\\“‘":
        return None, 2.5
    if len(s) == 1 and s.isupper():
        return None, 1.3
    if s and s[0].isupper():
        return None, 0.5
    return None, 0.0

programs.sol:
"""Approximate the component's negative web/contact-pointer response.

Recognise URL syntax, domains, handles, hashtag/reference signs and a small
web/contact vocabulary. Recent contact/social words strengthen some markers;
code syntax and indentation weaken many of them. 'Look at' is slightly
positive; other 'at' uses are negative, especially after contact language.
Unrecognised tokens get zero. A 256-character history resets per document.
Small lexical fluctuations and finer locative/measurement cues are omitted.
"""
import re

READS = ()
WORDS = {}
# A small vocabulary of online sites, contact methods and reference terms.
for words, value in (
    ('website 网站 官网 主页 сайте сайта email emails 邮箱', -1.3),
    ('websites blog blogs blogger ブログ', -0.7),
    ('site сайт github ithub mail channel', -0.5),
    ('web sites contact follow link links url online tag tags handle', -0.3),
    ('instagram', -2.6),
    ('twitter facebook linkedin 微博 官方微博', -1.9),
    ('youtube vimeo', -1.2),
    ('pinterest skype whatsapp yahoo 微信', -1.6),
    ('网址 網址', -2.4),
    ('公众号 微信号', -3.4),
    ('热线 电话 電話 手机号', -0.9),
    ('二维码 二維碼', -1.9),
    ('hashtag hashtags', -3.1),
):
    WORDS.update(dict.fromkeys(words.split(), value))
CODE = re.compile(r'[{}=]|\$[A-Za-z_]|\b(public|private|const|import|def)\b')
CONTACT = re.compile(
    r'\b(website|blog|online|contact|email|mail|visit|reach|follow|'
    r'twitter|facebook|instagram)\b', re.I
)
SOCIAL = re.compile(r'\b(twitter|facebook|instagram|youtube|vimeo|flickr)\b', re.I)
DOMAINS = {'.com', '.co', '.org', '.edu', '.gov', '.net', '.uk', '.jp', '.ru',
           '.io', '.de', '.ua', '.cn'}


def response(token, past, position):
    word = token.strip().lower()
    code = bool(CODE.search(past[-180:]))
    contact = bool(CONTACT.search(past[-100:]))
    social = bool(SOCIAL.search(past[-80:]))
    line = past.rsplit('\n', 1)[-1]
    if '://' in token:
        if past.lower().endswith('file'):
            return -0.3
        return -4.4 if contact else (-2.8 if code else -3.7)
    if word.strip('.,-。') == 'www':
        if code and token.strip().isupper():
            return -0.4
        return -3.7 if token.startswith(' ') else -2.7
    if '@' in token or '＠' in token:
        if '[@' in token:
            return -1.0
        if '＠' in token:
            return -3.2
        if word in ('@gmail', '@yahoo', '@hotmail', '@mail'):
            return -3.6
        if word in ('@example', '@email'):
            return -2.4
        if re.search(r'\btwitter\s*(at\s*)?$', past[-40:], re.I):
            return -7.4
        if social:
            return -4.6
        if code or (not line.strip() and token in ('@', ' @')):
            return -0.44
        if '(' in token or contact:
            return -2.7
        return -1.2 if len(word) == 1 else -0.1
    if '#' in token:
        if word == '##':
            return 0.02
        if word == '###':
            return -0.35
        if len(word) > 3 and set(word) == {'#'}:
            return -0.17
        if '[#' in token:
            return -1.56
        if position == 0:
            return 0.27
        indented = (bool(re.fullmatch(r'\s*(\d+[ \t]+)?\s*', line))
                    or line.endswith(('  ', '\t')))
        if code or (indented and token.startswith(' ')):
            return -0.08
        if not line.strip():
            return -0.32
        return -1.35 if token.startswith(' ') else -0.42
    if word in DOMAINS:
        if re.search(r'(twitter|facebook|youtube|vimeo|flickr)$', past, re.I):
            return -4.3
        value = -1.3 if word == '.com' else -0.7
        return value * (0.7 if code else 1.0)
    if word == 'at' and (token[0].isspace() or position == 0):
        if re.search(r'\b(look|looked|looking|looks|glance|stare|staring)\s*$',
                     past[-40:], re.I):
            return 0.14
        if contact:
            return -0.8
        return -0.17 if token.strip() == 'At' else -0.37
    if word == 'media' and past.lower().rstrip().endswith('social'):
        return -1.84
    if word == 'address' and past.lower().rstrip().endswith(('email', 'mail')):
        return -1.7
    if (word == 'page' and token.startswith(' ')
            and past.lower().rstrip().endswith('facebook')):
        return -4.8
    if word in ('http', 'https'):
        return -0.06 if code else (-1.5 if contact else -0.7)
    if word in ('-mail', '[email'):
        return -2.0
    value = WORDS.get(word, 0.0)
    if code and word in ('email', 'site', 'web', 'tag', 'channel', 'website'):
        value *= 0.3
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        past, position = '', 0
    else:
        _, past, position = carry
    token = prefix.token_strings[-1]
    value = response(token, past, position)
    return (doc, (past + token)[-256:], position + 1), value

programs.luna:
"""A small lexical sketch of the component's mostly negative token responses.
It marks URL/email syntax, web/contact vocabulary, and the word 'at'.
"""
READS = ()

WEB_WORDS = {
    "blog", "website", "websites", "site", "series", "email", "contact",
    "call", "code", "公众号", "访问", "ブログ", "店",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()

    if "://" in token:
        return None, -3.4
    if "@" in token:
        return None, -2.3
    if word == "at":
        return None, -0.6
    if word in WEB_WORDS:
        return None, -0.7
    if word.startswith("[") and "email" in word:
        return None, -1.5
    if word.startswith("#") or word == "#":
        return None, -0.4
    if ".com" in word:
        return None, -0.35
    if "£" in token:
        return None, -0.8
    return None, 0.0

programs.sol:
"""An onset/change-of-state word detector with one-token continuation.

The strongest signals are inflected forms of 'start' and 'begin'. Related
initialization, becoming, opening, completion and upward-change words are
weaker. Some common translations are recognized too. Verbal contexts amplify
beginnings, which can persist onto the next linking word. 'First', 'new' and
'back' are mildly negative. Explicit action/reasoning delimiters have fixed
values. Other words are zero; regular English inflections are recognized and
small idiosyncratic lexical effects are deliberately not modeled.
"""
import re

READS = ()
START = {
    'start': 2.55, 'starts': 3.15, 'started': 4.5, 'starting': 3.5,
    'starter': 3.1, 'startup': 2.5, 'startups': 2.5, 'startswith': 2.5,
    'restart': 1.9, 'restarted': 2.4,
    'begin': 1.9, 'begins': 2.5, 'began': 3.1, 'begun': 2.6,
    'beginning': 1.85, 'beginnings': 2.0,
}
# Graded, familiar word classes (space-separated to keep the lexicon readable).
CLASSES = (
    (2.3, 'initiate initiated initiating initiation commence commenced'),
    (1.1, 'initial initially initialize initialization early birth'),
    (1.45, 'init launch onset'),
    (1.2, 'become became emerge arise'),
    (0.8, 'open enter entry exit finish stop lead led origin spring came '
          'welcome introduce introduction prompt setup trigger debut founded '
          'initiative initiatives'),
    (0.55, 'complete increase grow grew rise born learn morning soon ready '
           'gain discover background foundation'),
    (0.4, 'come into up got'), (0.25, 'get out off place'),
    (-0.13, 'first new'), (-0.28, 'back'),
    # Beginning, rising, opening, and emergence in East Asian languages.
    (2.7, '开始 開始 启动 啟動 开启 開啟 起步 始 始め 시작 スタート 发起'),
    (2.3, '起'), (3.2, '启 啟'),
    (1.6, '起了 新开 出发 起こ はじめ 创业 动手 引起'),
    (1.1, '开 開 起来 起來 春 初 发 發 一起 부터 になって になり'),
    (0.75, '来 來 出 进入 出现 发现 发出 完 先 から'),
)
WORDS = {word: value for value, words in CLASSES for word in words.split()}
REGULAR_VERBS = set(
    'initialize launch become emerge arise open enter exit finish stop lead '
    'introduce prompt trigger complete increase grow rise learn gain discover '
    'come get welcome'.split()
)


def inflection_value(word):
    """Try ordinary English plural, progressive, and past-tense endings."""
    if word in WORDS:
        return WORDS[word]
    if word.endswith('s') and word[:-1] in WORDS:
        return WORDS[word[:-1]]
    for ending in ('ing', 'ed', 'es', 's'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            roots = [stem, stem + 'e']
            if len(stem) > 1 and stem[-1] == stem[-2]:
                roots.append(stem[:-1])
            for root in roots:
                if root in REGULAR_VERBS:
                    return WORDS[root]
    return 0.0


SUBJECTS = set('i we you he she it they'.split())
VERB_CUES = SUBJECTS | set('to can could will would should must not'.split())
LINKS = set(
    'a an the his her my your our their its of with in at from by on as'.split()
)
FOREIGN_START = ('нач', 'comenz', 'empez', 'commenc', 'begann', 'beginn',
                 'anfang', 'début', 'começ')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous, strength = carry
    text = prefix.token_strings[-1]
    # Ignore spaces and common code/filename separators before a word.
    raw = text.strip().lstrip('._-/([{<')
    identifier = re.match(r'(start|Start|START|begin|Begin|BEGIN)(?=[A-Z_])', raw)
    word = identifier.group(1).lower() if identifier else raw.lower()
    value, onset = inflection_value(word), False
    if word in START:
        value, onset = START[word], word != 'startswith'
        if not text[:1].isspace():
            if word == 'begin':
                value = 1.4 if raw[0].isupper() else 0.52
            elif word != 'startswith' and not (
                word == 'starting' and raw[0].isupper()
            ):
                value *= 0.8
        if text.startswith(('/start', '-start')):
            value = 3.2
        if identifier:
            value, onset = (2.1 if word == 'start' else 1.6), False
    elif word.startswith(('initiat', 'commenc')):
        value, onset = value or 2.2, True
    elif '开始' in word or '開始' in word:
        value, onset = 2.7, True
    elif text[:1].isspace() and word.startswith(FOREIGN_START):
        value, onset = 2.2, True
    if word in {'start', 'begin'} and previous in VERB_CUES:
        value += 0.55
    if word == 'started' and previous in SUBJECTS:
        value += 0.4
    if word == 'starting' and previous == 'before':
        value += 1.5
    elif word == 'starting' and previous in {'is', 'are', 'was', 'after'}:
        value += 0.5
    if not text[:1].isspace() and word == 'led':
        value = 0.05  # Often the suffix of 'called', not the verb 'led'.
    # Only the immediately previous token can supply this continuation.
    if strength:
        if word == 'to':
            value += 0.52 * strength
        elif word in LINKS or word in {'up', 'out', 'off'}:
            value += 0.27 * strength
    value = {'<tool_call>': 0.96, '<think>': 0.32,
             '<tool_response>': -0.27}.get(text, value)
    return (doc, word, value if onset else 0.0), float(value)

programs.haiku:
"""Words of starting and beginning, and weaker words of change, completion, and the word that follows them.

A reader's sketch: the component reads the lexical signal "something is starting or changing phase".
Its value is a graded score on the current token, with previous-token context for the
word after a start verb ("started to", "start of") and for "up" after "end"/"set"/"wind" etc.
"""
READS = ()

START = {"start", "starts", "started", "starting", "startup", "begin", "begins", "began", "beginning",
         "beginner", "beginners", "initiate", "initiated", "initiation"}
CHANGE = {"become", "becomes", "became", "becoming", "birth", "launch", "launched", "open", "opened",
          "early", "lead", "leads", "led", "came", "initial", "initially", "init", "initialize",
          "introductory"}
ENDING = {"finish", "finished", "complete", "completed", "stop", "stopped", "resume", "resumed",
          "learn", "learned", "grow", "soon", "ready"}
AFTER_START = {"to", "of", "into"}
UP_AFTER = {"end", "ended", "ends", "set", "wind", "winding", "grow", "came", "take", "ending", "waking"}

def word(token):
    return token.strip().lower().lstrip("-.")

def step(carry, prefix, upstream):
    tok = word(prefix.token_strings[-1])
    prev = word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if tok in START:
        value = 2.8
    elif tok in CHANGE:
        value = 0.95
    elif tok in ENDING:
        value = 0.6
    elif tok in AFTER_START and prev in START:
        value = 1.6
    elif tok == "up" and prev in UP_AFTER:
        value = 0.85
    else:
        value = 0.0
    return None, value

programs.luna:
"""Approximate an onset/transition signal with familiar word families.

The clearest responses are to starting and entering; related change and
emergence words get smaller values. Context not named here is left at zero.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    if word.startswith(("begin", "began", "start", "initi", "commenc")):
        return None, 2.2
    if word.startswith(("open", "entry", "enter", "exit", "arriv", "birth")):
        return None, 0.8
    if word.startswith(("emerg", "arise", "appear", "launch", "creat")):
        return None, 0.65
    if word.startswith(("increas", "grow", "develop", "awak", "resurrect")):
        return None, 0.55
    if word.startswith(("first", "initial", "origin", "onset", "morning", "soon")):
        return None, 0.55
    if word.startswith(("stop", "complet", "finish", "lead", "acquir")):
        return None, 0.5
    if word.startswith(("rudiment", "upbring")):
        return None, 0.6
    if word in {
        "来", "动手", "醒", "发出", "印发", "になって",
        "vrir", "zunächst", "prompt",
    }:
        return None, 0.8
    if word == "out":
        return None, 0.35

    # An infinitival "to" also responded after "began" in an example.
    if word == "to" and len(prefix) > 1:
        previous = prefix.token_strings[-2].strip().casefold()
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        if same_document and previous.startswith(("begin", "began", "start", "initi")):
            return None, 1.6

    return None, 0.0

programs.sol:
"""Mark capitalized pieces inside joined names, not space-separated words.

A camel/Pascal-case continuation has a positive signal, strengthened after an
acronym or for basic programming types and fields. Short fragments and
continuations after digits are weaker.
At document onset the sign reverses for bare capitalized words, headings and
source-code directives. Literal escaped whitespace breaks a joined name.
All state resets at a document boundary.
"""
READS = ()
SENTENCE_OPENERS = frozenset('''The This These Those An We You It There What
How Why Where When Which Who Welcome Hello Hi Sorry Today Yesterday
Tomorrow'''.split())
WEEKDAYS = frozenset('''Monday Tuesday Wednesday Thursday Friday Saturday
Sunday'''.split())
TYPES_AND_FIELDS = frozenset('''Array List Map Set String Int Type Class Struct
Enum Object Bool Boolean Float Double Byte Char Integer Dictionary Tuple Vector
Id Name Key Value Data Index Size Count Length Code Status State Version
Number'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    title = (len(token) > 1 and 'A' <= token[0] <= 'Z'
             and 'a' <= token[1] <= 'z')
    value = 0.0
    if first:
        if token in SENTENCE_OPENERS or token in WEEKDAYS:
            value = -2.5
        elif token in ('package', 'import'):
            value = -2.2
        elif title:
            value = -1.25
        elif token in ('A', 'I'):
            value = -1.3
        elif token.startswith('#'):
            value = -2.5 if token == '##' else -1.55
        elif token in ('//', '/*', '<?'):
            value = -1.35
        elif token.isascii() and token.isalpha() and token.isupper():
            value = -0.35
    elif title and not tail.endswith(('\\n', '\\r', '\\t')):
        last = previous[-1:] or ' '
        if last.isascii() and last.isalpha():
            value = 0.85
            if len(token) == 2:
                value -= 0.20
            elif len(token) == 3 or len(token) >= 8:
                value -= 0.10
            if len(previous) <= 2:
                value -= 0.15
            if last.isupper():
                value += 0.55
            if sum(c.isupper() for c in token) > 1:
                value *= 0.5
            if token in TYPES_AND_FIELDS:
                value += 0.20
        elif last.isascii() and last.isdigit():
            value = 0.29
    return (doc, token, (tail + token)[-4:]), float(value)

programs.luna:
"""Recognize the capital boundary inside a joined, camel-cased name."""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None:
        return (doc, token), 0.0
    previous_doc, previous = carry
    joined_name = (
        doc == previous_doc and previous and previous[-1].isalnum()
        and token and token[0].isupper()
    )
    return (doc, token), (0.4 if joined_name else 0.0)

programs.sol:
"""Approximate the component's lexical, information-handling responses.

Its clearest negative responses complete source-code names, storage nouns,
export declarations, and save/copy/input/output phrases. The small vocabulary
below describes those compounds, not token IDs. URL separators and message
boundaries have separate responses. All other text gets a near-zero baseline;
the component's many small, vocabulary-specific fluctuations are not modeled.
"""
READS = ()

# Each group lists recognizable completions of an information-handling word.
COMPLETIONS = {
    'source': [
        ('code', -0.90), ('map maps root', -0.75),
        ('tree material', -0.50), ('file files context type lines', -0.20)],
    'storage': [
        ('unit', -1.25),
        ('space spaces area areas room capacity tank units account engine '
         'class manager layout local sync', -0.85),
        ('device devices media medium service exception facility facilities', -0.59),
        ('system systems', -0.38), ('module object dir', -0.21)],
    'stored': [('in on', -0.43), ('value', -0.74)],
    'store': [('in on', -0.36), ('value true', -0.46), ('front house', -0.95)],
    'export': [('class', -0.76), ('function async', -0.48),
               ('const default declare', -0.37), ('interface type path', -0.29)],
    'save': [('for as', -0.95), ('primitive', -0.64), ('lives', -0.76),
             ('on space time', -0.40), ('money up', -0.26)],
    'saving': [('lives', -0.76), ('time money grace', -0.35)],
    'copy': [('res', -0.73), ('number on deepcopy', -0.56),
             ('writing writer with', -0.47)],
    'output': [('layer', -0.74), ('builder voltage power shaft impedance', -0.45),
               ('format', -0.26)],
    'input': [('error document valid', -0.49)],
    'print': [('exc function', -0.65)],
    'return': [('true false null none new res err', -0.16),
               ('value values on', -0.28)],
    'record': [('set sets', -0.48), ('label', -0.22)],
    'stock': [('holders holder split ownership', -0.51),
              ('market price prices photo exchange', -0.35)],
}
COMPLETIONS = {
    stem: [(set(words.split()), value) for words, value in groups]
    for stem, groups in COMPLETIONS.items()
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    p = previous.strip().lstrip('./_').lower()
    c = word.lstrip('./_-').lower()
    value = -0.004
    if not word:
        value = 0.001
    elif word.isdecimal():
        value = -0.002
    elif word.isascii() and not any(ch.isalnum() for ch in word):
        value = 0.0025
    if c in {'source', 'storage', 'store', 'copy', 'record'}:
        value = -0.05
    if p in COMPLETIONS and any(ch.isalpha() for ch in word):
        value = -0.08
        for words, response in COMPLETIONS[p]:
            if c in words:
                value = response
                break
        if p == 'export' and previous.startswith('\t'):
            value *= 0.5
    if p == 'source' and previous.strip() == 'Source':
        if c == 'code':
            value = -1.02
        elif c == 'file':
            value = -0.63
    if p == 'output' and word == 'Format':
        value = -0.90
    if p == 'print' and word.startswith('(f'):
        value = -0.13
    if p == 'record' and word.startswith('<string'):
        value = -0.49
    if previous.strip() == 'Share' and c in {'on', 'point', 'through'}:
        value = -0.79 if c != 'through' else -0.44
    if previous.strip() == '/store' and word in {'/actions', '/modules'}:
        value = -1.0
    if previous.strip() in {'存储', '储存'}:
        value = -0.80 if word in {'空间', '库'} else -0.15
    if previous.strip() == '保存':
        value = {'到': -0.64, '为': -1.10}.get(word, -0.15)
    if previous.strip() == '保':
        value = -0.20
        if word in {'单', '單'}:
            value = -0.76
        elif word in set('温溫育本监監候特'):
            value = -0.50
    if p in {'http', 'https'} and word == '://':
        value = 0.12
    if word == '<|im_start|>':
        value = 0.115 if not previous else 0.015
    elif word == '<|im_end|>':
        value = -0.14 if previous.rstrip().endswith(('.', '?', '。')) else -0.04
    elif word == '</tool_call>':
        value = 0.08
    elif word in {'<think>', '</think>'}:
        value = -0.06
    elif word == 'import' and previous.rstrip().endswith(';'):
        value = -0.13
    return (doc, token), float(value)

programs.luna:
"""Predict negative spikes for a few recognizable storage and code contexts.

The large activations in the examples cluster around storage terms, source
code, and a few short phrases. Other tokens get zero rather than guessed noise.
"""

READS = ()

STORAGE_WORDS = {"account", "capacity", "space", "room", "units", "area"}


def step(carry, prefix, upstream):
