    elif word == "class" and (
        "export" in before[-48:] or "storage" in before[-48:]
    ):
        value = -0.8
    elif word == "next" and "return" in before[-48:]:
        value = -0.8
    elif word == "res" and "imagecopy" in before[-48:]:
        value = -0.75
    elif word == "/modules" and "store" in before[-48:]:
