programs.sol:
"""Approximate the first value on the right-hand side of an equality.

Usually predict a positive burst after an assignment/comparison operator.
Literal and programming-word classes set its strength; whitespace carries
rather than consumes the cue. LaTeX backslashes can also carry it forward.
Bare equality signs are usually negative, particularly near document start
or another equality. Chinese 是 patterns and return expressions have related
responses. Document position calibrates the amplitude; all state resets when
the document changes. This is a surface heuristic, not a full expression parser.
"""
import re

READS = ()
NULLS = {'null', 'NULL', 'nil', 'None', 'nullptr'}
CREATORS = {'new', 'function', 'async', 'await'}
LIBRARIES = {'np', 'pd', 'numpy', 'pandas', 'torch', 'tf'}
# Common functions and namespace prefixes in value expressions.
CALLS = {'input', 'int', 'float', 'str', 'list', 'dict', 'set', 'tuple',
         'map', 'zip', 'range', 'len', 'min', 'max', 'sum', 'abs', 'open',
         'malloc', 'calloc', 'realloc', 'get', 'make', 'create', 'load',
         'read', 'fetch', 'parse', 'find', 'document', 'window', 'Math',
         'React', 'JSON'}
# Predicate starters: grammatical verbs, pronouns, questions and classifiers.
CHINESE_STARTERS = set('''有 要 需要 以 由 在 用 不 對 对 把 将 將 被
    個 个 的 啊 说 說 指 从 從 根据 根據 關於 关于 为了 為了 很 太 最
    更 會 会 能 可以 可能 应该 應該 必须 必須 这样 這樣 什麼 什么
    如何 怎么 怎麼 哪 何 誰 谁 我 你 他 它 我们 我們 自己 您 想 不能
    通过 通過 由于 由於 无法 無法 这样的 這樣的 那么 那麼 如此 什麽
    一 一个 一個 一种 一種 种 種 位 件'''.split())
DISCOUNTS = {'==': .2, '===': .2, '!=': .53, '!==': .53,
             '<=': .57, '>=': .57, ':=': .25}
START_SIGNS = {'=': -4.0, ':=': -2.55, ')=': -2.86,
               '}=': -2.86, ']=': -2.86, ':': -.6, '是': -2.56}


def value_strength(text):
    word = text.strip()
    if not word:
        return 1.0 if text.startswith('\xa0') else -.18
    if word.isdigit():
        return 1.1 if word in {'0', '1', '2'} else .85
    if word == 'require':
        return 3.2
    if word in NULLS or word in CREATORS or word in LIBRARIES:
        return 1.9
    if word in CALLS:
        return 1.5
    if word in {'self', 'super'}:
        return 1.4
    if word in {'false', 'False'}:
        return 1.08
    if word in {'true', 'True'}:
        return .77
    if word in {'-', '−'}:
        return 1.55
    if word.startswith(('[]', '{}')):
        return .75 if '\n' in text or ';' in word else .5
    if word.startswith(("['", '["', "('", '("')):
        return -.3
    if word.startswith(('\\"', "\\'")):
        return .15
    if word.startswith(('"', "'", '`', '[', '{')):
        return .1
    if word.startswith('\\'):
        return .9 if text.startswith(' ') else 1.5
    if word.startswith('('):
        return .3 if len(word) > 1 and word[1] == '(' else .8
    if len(word) == 1 and word.isascii() and word.isalpha():
        return .85 if text.startswith(' ') else 1.25
    return .8 if word.islower() else .6


def trailing_operator(text):
    if '\n' in text or '\r' in text:
        return ''
    if text.endswith('<-') or text.strip() == '≈':
        return '='
    match = re.search(r'([=!:<>+*/&|^-]*=)$', text)
    return match.group(1) if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending, distance, position = '', '', 99, 0
    else:
        _, previous, pending, distance, position = carry
        position += 1
    text = prefix.token_strings[-1]
    word = text.strip()
    op = trailing_operator(previous) or pending
    value = 0.0
    if op:
        default_discount = 0.0 if op in {'=', '&=', '|='} else .32
        discount = DISCOUNTS.get(op, default_discount)
        value = value_strength(text) - discount
        value += .75 / position if position else 0.0
        value -= .12 if pending else 0.0

    merged = re.match(r'^[)}\]]?=([^=>].*)$', word)
    if merged:
        body = merged.group(1)
        value = (.52 if body in {'"', "'"}
                 else max(1.1, value_strength(body)))
        if body == '\\':
            value = .35
        value -= 1.4 if distance <= 2 else 0.0
        if position == 0:
            value = -2.2 if len(word) <= 2 else -.3
    elif word and '=' in word and set(word) <= set('=:!<>+*/&|^-'):
        value = -.1
        if word == ':=':
            value = -.28
        elif len(word) >= 4 and set(word) == {'='}:
            value = (-1.4 if distance <= 2
                     else -.7 if len(word) <= 8 else .25)
        elif word == '=':
            value -= 1.2 if distance <= 1 else .65 if distance <= 2 else (
                .2 if distance <= 6 else 0.0)
        value -= .9 if position == 1 else .2 if position == 2 else 0.0
    elif word in {')=', '}=', ']='}:
        value = -1.1 if position == 1 else -.18
    elif word in {'≈', 'equal', 'equals'}:
        value = -.35 if word == '≈' else -.18

    if position == 0:
        value = START_SIGNS.get(word, value)
    if previous.strip() == 'return' and not op:
        value = .4 * max(0.0, value_strength(text))
    if previous.endswith('是') and previous not in {'但是', '于是', '於是'}:
        if word and all('\u4e00' <= c <= '\u9fff' for c in word):
            value = 1.55 if word in CHINESE_STARTERS else .35
    if word.startswith('是') and len(word) > 1:
        value = 1.2 if word[1:] in CHINESE_STARTERS else .65
    if previous.strip() == '===' and word == 'RUN':
        value = .89
    pending = op if not word and '\n' not in text else ''
    if word == '=\\' or (op and word == '\\'):
        pending = '='
    # Distance counts tokens since the most recent equals sign.
    distance = 0 if '=' in text else distance + 1
    return (doc, text, pending, distance, position), float(value)

programs.haiku:
"""Fires on the first token of a value after an assignment or equality operator.

In code and math, the component reads the token just after `=`, `==`, `!=`, `:=`, `+=`
and similar (not `=>`, `<=`, `>=`), when that token starts the right-hand side: a
keyword such as null, NULL, nil, new or function, a number, or a plain word. Quotes,
brackets, braces, `$` and `\\` starts barely fire. A space between the operator and
the value is skipped, so `x = 1` fires on the `1`. Everywhere else it is near 0.
"""

READS = ()

NULL_WORDS = {"null", "NULL", "nil", "new", "function", "None", "undefined"}
OPEN_STARTS = set("\"'`{[($\\")


def is_assign_op(text):
    t = text.strip()
    return t.endswith("=") and t[:1] not in ("<", ">") and not t.startswith("=>")


def value_strength(text):
    s = text.lstrip()
    if not s:
        return 0.0
    if s in NULL_WORDS:
        return 1.6
    if s[0].isdigit():
        return 1.1
    if s == "-":
        return 1.5
    if s[0].isalpha() and s.isascii():
        return 0.9
    if s[0] in OPEN_STARTS or s[0] == "$":
        return 0.2
    return 0.5


def step(carry, prefix, upstream):
    ids = prefix.token_ids
    docs = prefix.document_ids
    strings = prefix.token_strings
    t = len(ids) - 1
    if t < 1 or docs[t - 1] != docs[t]:
        return carry, 0.0
    if is_assign_op(strings[t - 1]):
        return carry, value_strength(strings[t])
    if t >= 2 and strings[t - 1].strip() == "" and docs[t - 2] == docs[t] and is_assign_op(strings[t - 2]):
        return carry, 0.9 if strings[t][:1].isdigit() else 0.0
    return carry, 0.0

programs.sol:
"""Approximate the negative signal on Latin-shaped word continuations.

Recognize classical, scientific and diminutive endings, plus short vowel-ended
name fragments. Their fitted amplitudes use the preceding word stem's length,
capitalization and final vowel. All-capital fragments are attenuated.
Unrecognized fragments and tokens starting a word receive zero. Only ASCII
letters are tracked; word state resets at each document boundary.
"""
import re

READS = ()

LATIN_CASE = {'us', 'ius', 'um', 'ium', 'is', 'ae', 'as', 'es', 'os'}
SCIENTIFIC = {'ensis', 'enses', 'itis', 'osis', 'ysis', 'oma', 'aceous',
              'coccus', 'occus', 'cocci', 'ceps', 'iceps'}
FAMILY_FRAGMENTS = {'ida', 'idae', 'aceae', 'inae'}
CLASSICAL_ADJECTIVES = {'atus', 'alis', 'aris', 'anus', 'inus',
                        'arius', 'arium', 'iana', 'ianus', 'ianae'}
SHAPE_ENDINGS = {'iform', 'iformis', 'opsis'}
DIMINUTIVES = {'ella', 'illa', 'illo', 'etta', 'etto', 'elle', 'elli',
               'ola', 'olo', 'ula', 'ulo', 'ulus', 'illus', 'ulae'}
ENGLISH = {'s', 'ed', 'ing', 'er', 'ers', 'est', 'ly', 'ness', 'ment',
           'tion', 'ions', 'ion', 'ity', 'able', 'ible', 'ful', 'less'}


def ending_class(s):
    if not (s.isascii() and s.isalpha() and len(s) <= 8):
        return 'other'
    s = s.lower()
    if s in ENGLISH:
        return 'english'
    if s in FAMILY_FRAGMENTS:
        return 'family_fragment'
    if s in CLASSICAL_ADJECTIVES:
        return 'classical_adjective'
    if s in SHAPE_ENDINGS:
        return 'shape'
    if s in SCIENTIFIC:
        return 'scientific'
    if s in LATIN_CASE:
        return s
    if s in DIMINUTIVES or s.rstrip('s') in DIMINUTIVES:
        return 'diminutive'
    if len(s) >= 3 and s.endswith(('us', 'um', 'is', 'es', 'as', 'os')):
        if s.endswith('ous'):
            return 'english'
        return 'long_' + s[-2:]
    if len(s) == 1 and s in 'aeiou':
        return s
    if 2 <= len(s) <= 5 and s.endswith('a'):
        return 'vowel_a' if s[0] in 'aeiou' and len(s) >= 3 else 'other_a'
    if 2 <= len(s) <= 5 and s.endswith(('i', 'o', 'u')):
        return 'vowel_iou' if s[0] in 'aeiou' and len(s) >= 3 else 'other_vowel'
    if s in {'ian', 'ians', 'arian'}:
        return 'derived_latin'
    if s in {'ine', 'ene', 'ane', 'one', 'ace', 'ite',
             'oid', 'oids', 'ops', 'oph', 'ic', 'ics'}:
        return 'technical'
    return 'other'


# Fitted coefficients for recognizable ending classes, not token IDs.
# Columns: offset, stem length (capped at 8), capitalization, final vowel.
WEIGHTS = {
    'a': (0.0364, -0.062, -0.1769, -0.2087),
    'ae': (0.0999, -0.1038, -0.0678, -0.1484),
    'as': (0.2254, -0.0632, -0.0886, -0.0406),
    'classical_adjective': (-0.5044, -0.1338, -0.119, -0.1299),
    'derived_latin': (0.0583, -0.04, -0.1369, -0.0041),
    'diminutive': (0.0067, -0.0986, -0.1922, 0.1006),
    'e': (0.1366, -0.0372, -0.0565, -0.1871),
    'english': (0.0299, -0.0008, -0.0032, 0.0105),
    'es': (0.1275, -0.0429, -0.1085, -0.0534),
    'family_fragment': (-0.0076, -0.1253, -0.8306, -0.2027),
    'i': (0.0699, -0.0413, -0.1307, -0.0183),
    'is': (-0.0749, -0.0742, -0.0797, 0.1315),
    'ium': (-0.4213, -0.0605, 0.0212, 0.1815),
    'ius': (-0.3559, -0.1287, -0.19, 0.0697),
    'long_as': (0.0331, -0.0273, -0.166, 0.0208),
    'long_es': (0.01, -0.0153, -0.0452, -0.0058),
    'long_is': (-0.1083, -0.0289, -0.06, 0.021),
    'long_os': (0.0168, -0.0193, -0.1008, 0.0279),
    'long_um': (-0.0753, -0.0284, 0.0055, 0.1099),
    'long_us': (-0.1749, -0.045, -0.0803, -0.1204),
    'o': (0.0788, -0.022, -0.1052, -0.0792),
    'os': (0.0816, -0.0453, -0.1211, 0.0066),
    'other_a': (-0.0121, -0.0345, -0.1541, -0.0409),
    'other_vowel': (0.0178, -0.0115, -0.0704, -0.0107),
    'scientific': (-0.4522, -0.0539, -0.001, -0.0714),
    'shape': (-0.2004, -0.2016, -0.1162, -0.5338),
    'taxonomic_family': (-0.2651, -0.0604, -0.2376, -0.3781),
    'technical': (0.0406, -0.0357, -0.0714, 0.0547),
    'u': (0.0294, -0.0164, -0.0897, 0.0014),
    'um': (0.0779, -0.0849, -0.0197, -0.0641),
    'us': (0.0553, -0.15, -0.103, -0.1173),
    'vowel_a': (-0.0421, -0.0575, -0.2597, -0.06),
    'vowel_iou': (-0.001, -0.0169, -0.1787, 0.0057),
