def features(token, previous):
    kind = ending_class(token)
    if not previous or kind == 'other':
        return None
    whole = (previous + token).lower()
    if len(previous) >= 4 and len(token) <= 5:
        if whole.endswith(('idae', 'aceae', 'inae')):
            kind = 'taxonomic_family'
        elif whole.endswith(('iformis', 'icornis', 'opsis')):
            kind = 'shape'
        elif whole.endswith(('ensis', 'aceous', 'coccus', 'iceps')):
            kind = 'scientific'
    return kind, (1.0, min(8, len(previous)),
                  float(previous[0].isupper()),
                  float(previous[-1].lower() in 'aeiou'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    feat = features(token, previous)
    value = 0.0
    if feat is not None:
        kind, x = feat
        value = sum(a * b for a, b in zip(WEIGHTS.get(kind, (0, 0, 0, 0)), x))
        if token.isupper():
            value *= 0.4
    if token.isascii() and token.isalpha():
        word = (previous + token)[-40:]
    else:
        match = re.search(r'[A-Za-z]+$', token)
        word = match[0] if match else ''
    return (doc, word), float(value)

"""Recognize token spellings associated with fractional portions.

Half (also 半 and ½) dominates; quarters and semi-/demi-/hemi- are
weaker. Completeness, ordinals and multiplicity give small responses.
The detector also reacts to unfinished 'hal', 'alf', and 'sem' tokens,
not only meaningful uses. Fraction-following 'of' and half-following
articles retain a response. Other tokens get zero; documents reset state.
"""
READS = ()
ORDINALS = frozenset('third fourth fifth sixth seventh eighth ninth tenth '
                     'eleventh twelfth thirteenth fourteenth fifteenth '
                     'sixteenth seventeenth eighteenth nineteenth twentieth'.split())
ORDINAL_ENDINGS = frozenset('ighth ifth venth elfth teenth eenth entieth'.split())
COMPLETENESS = frozenset('partial partially partly fully almost nearly'.split())
MULTIPLICITY = frozenset('double doubled doubles multiple dual'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    s = raw.strip()
    word = s.strip('._-/\\()[]{}:,;"\'').lower()
    spaced = raw[:1].isspace()
    value = 0.0
    if word == 'half':
        value = 7.2 if s.startswith('_') else 9.6 if spaced else 8.9
    elif word in {'halves', 'halfway', 'halftime'}:
        value = {'halves': 4.3, 'halfway': 5.5, 'halftime': 3.5}[word]
    elif word == 'quarter':
        value = 4.6 if spaced and s.islower() else 3.8
    elif word in {'quarters', 'quarterly'}:
        value = 3.1 if word == 'quarters' else 2.0
    elif word in {'½', '¼', '¾'}:
        value = 5.5 if word == '½' else 1.3
    elif s in {'半', '一半', '下半', '上半'}:
        value = 8.0
    elif '半' in s:
        value = 1.4 if s.endswith(('导体', '導體')) else 3.5
        if s == '另一半':
            value = 5.5
    elif raw == '\ufffd' and prefix.text_prefixes[-1].endswith('半'):
        value = 10.5  # A split character's final byte completes 'half'.
    elif word in {'semi', 'semif', 'demi', 'hemisphere'}:
        value = 2.4 if word == 'hemisphere' else 3.4
    elif word in {'sem', 'hal', 'alf', 'semester', 'semiconductor'}:
        value = 1.7
        if word == 'alf':
            value = 1.1 if spaced else 3.7
    elif word == 'full':
        value = 1.2
    elif word in COMPLETENESS:
        value = 0.8 if spaced else 0.25
    elif word in ORDINALS or word in ORDINAL_ENDINGS or word == 'thirds':
        value = 2.1 if s.startswith('-') or word == 'thirds' else 1.1
    elif word in {'st', 'nd', 'rd', 'th'} and prev[-1:].isdigit():
        value = 0.55 if word == 'st' else 0.75
    elif word == 'twice':
        value = 2.0
    elif word in MULTIPLICITY:
        value = 0.8
    elif word in {'triple', 'mid', 'near'}:
        value = 0.5
    elif word in {'two', 'few', 'pair', 'couple'}:
        value = 0.25

    previous = prev.strip().strip('-').lower()
    if word == 'of':
        value = {'half': 3.95, 'quarter': 3.25, 'halves': 2.1,
                 'quarters': 2.1, 'third': 0.75, 'thirds': 0.75,
                 'full': 0.3}.get(previous, 0.0)
    elif previous == 'half' and word in {'a', 'an', 'the'}:
        value = {'a': 1.6, 'an': 1.0, 'the': 1.3}[word]
    return (doc, raw), value

programs.haiku:
"""A word detector for splitting things into halves, quarters and other parts.

The component's activation is set mostly by the word itself, and is largest for 'half'
(and 半, the Chinese for half, and ½). Next come quarter, semi-/demi-, then fractional
ordinals (third, fifth, ...). The word 'of' right after 'half' or 'quarter' ('half of')
also gets a large value. Words like full, almost, nearly, and double, twice, multiple get
a small value, and an ordinal suffix after a number ('26th') a little. Everything else is 0.
"""

READS = ()

HALF = {"half", "halves", "halfway", "-half"}
QUARTER = {"quarter", "quarters", "quarterly"}
SMALL_FRACTION = {"¼", "¾"}
SEMI = {"semi", "demi", "sem", "semester", "hemisphere", "hemi"}
ORDINAL = {"third", "thirds", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth"}
DOUBLE = {"twice", "double", "doubled", "dual", "multiple", "双", "雙"}
WHOLE = {"full", "fully", "almost", "nearly", "partially", "partly", "midpoint"}


def word(token):
    return token.strip().lower().strip("-/")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    w = word(token)
    previous = word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if w in HALF:
        v = 9.0
    elif token.endswith("半"):
        v = 8.0
    elif "半" in token:
        v = 3.0
    elif w == "of" and previous in HALF | QUARTER:
        v = 4.0
    elif w == "½":
        v = 5.5
    elif w == "alf":
        v = 4.0
    elif w in QUARTER:
        v = 4.5
    elif w in SMALL_FRACTION:
        v = 1.5
    elif w in SEMI:
        v = 2.5
    elif w in ORDINAL:
        v = 1.1
    elif w in DOUBLE:
        v = 1.0
    elif w in WHOLE:
        v = 0.9
    elif w == "th" and previous[-1:].isdigit():
        v = 0.6
    else:
        v = 0.0
    return carry, float(v)

