programs.sol:
"""Detect the spelling family around 'ide', mostly with negative output.

Bare 'ide' and words like side, wide, slide, hide, ride, oxide, and ideal
are strongest; inflections and related fragments are weaker. A few
Cyrillic spellings and Chinese/Japanese counterparts are included.
This is not a general side/width topic detector: inside and outside,
for example, normally get zero. Only the previous token is remembered,
for split divide/decide/inside and local 'side of' phrases. The many
small responses on unrelated tokens are deliberately left at zero.
"""
READS = ()


def spelling_value(raw):
    word = raw.strip().lstrip('._-').lower()
    if word == 'ide':
        return -3.6 if raw.startswith(' ') else -4.3
    if word == 'ideo':
        return -2.0
    if word == 'lide':
        return -5.5
    if word == 'ides':
        return -3.3
    if word in ('ided', 'iding'):
        return -2.5
    if word in ('ider', 'iders'):
        return -1.9
    if word in ('iden', 'idence', 'idal', 'idable', 'identity', 'identities'):
        return -1.0
    if word == 'ride' and not raw[:1].isspace():
        return -4.3
    if word in ('side', 'wide', 'hide', 'slide', 'ride', 'glide',
                'oxide', 'chloride', 'fluoride', 'pride', 'tide', 'hyde'):
        if word == 'slide':
            return -3.7
        if word in ('ride', 'pride', 'tide', 'chloride', 'fluoride'):
            return -2.2
        return -2.9
    if word in ('sides', 'sided', 'wider', 'widest', 'riding', 'slider', 'aside'):
        return -1.6
    if word in ('slides', 'hides', 'sliding', 'hiding', 'rides', 'slid'):
        return -2.6
    if word.startswith('ideal'):
        return -2.6
    if word in ('idea', 'ideas', 'hidden', 'hid'):
        return -1.0
    if word in ('ptide', 'amide', 'otide'):
        return -1.6
    if word in ('icide', 'icides'):
        return -2.6
    if word == 'vide':
        return -2.7 if raw.strip() == 'Vide' else -1.5
    if word in ('hydro', 'ydro', 'hydrogen', 'video'):
        return -0.8
    if word.startswith('理想'):
        return -2.5 if word == '理想' else -1.4
    if word in ('側', '侧', '滑'):
        return -1.4
    if word in ('wid', 'width', 'widely', 'videos'):
        return -0.45
    if word in ('sidel', 'sidew', 'underside'):
        return -1.3
    if word == 'иде':
        return -2.4
    if word in ('ид', 'айд'):
        return -0.8
    # Related short syllables, rather than whole words containing 'd'.
    if not raw[:1].isspace() and word in (
        'ida', 'idi', 'ido', 'ade', 'ode', 'ude', 'ede'
    ):
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    value = spelling_value(raw)
    word = raw.strip().lower()
    # 'ide' completing divide/decide/inside is less strongly marked.
    if not raw[:1].isspace() and word in ('ide', 'ided', 'ides', 'iding'):
        if previous.lower().rstrip().endswith(('div', 'dec', 'ins')):
            value = -1.3
    # A short echo in the phrase 'side(s) of ...'.
    preceding_word = previous.strip().lstrip('._-').lower()
    if word == 'of':
        if preceding_word == 'side':
            value = -1.0
        elif preceding_word == 'sides':
            value = -0.45
    if word == 'side':
        if preceding_word in ('left', 'right', 'hand'):
            value = -2.0
        elif preceding_word in ('each', 'either', 'both'):
            value = -2.4
        elif preceding_word == 'the':
            value = -3.1
    return (doc, raw), float(value)

programs.haiku:
"""Lexicon candidate 4: graded negative activation for side / wide / ideal spellings and meanings."""
READS = ()

# The bare fragment "ide" is strongest.
BARE = {"ide", "lide", "icide", "иде"}
# Words built on "-side", "-wide", "-ride", "-hide", "-slide", "-tide", "-oxide", "ideal".
STRONG = {
    "ides", "ided", "iding", "ider", "side", "wide", "hide", "hides", "ride", "rides", "slide",
    "slides", "sliding", "glide", "tide", "oxide", "ideal", "ideally", "ideals", "hyde", "otide",
    "vide", "aide",
}
# Looser relatives: plural/derived "side" words, "wider", "pride", "idea", "ideal" in other scripts.
MEDIUM = {
    "sides", "sided", "widest", "wider", "pride", "aside", "slider", "hidden", "riding", "rider",
    "riders", "iders", "idea", "ideas", "ideo", "chloride", "fluoride", "homicide", "amide",
    "sideline", "sidelines", "underside", "bedside", "stride", "hiding", "hid", "slid", "fade",
    "beside", "suicide", "dioxide", "abide", "idle", "idol", "иде",
}
# Weakest: "video", "identity", "hydro" and other lookalikes.
WEAK = {
    "video", "videos", "identity", "identities", "ideology", "ideologies", "hydro", "hydrogen",
    "cider", "confidence", "iden", "idal", "ident", "identify", "residence", "reside", "resides",
    "coincide", "decide", "wade", "rode", "siding", "width",
}

def step(carry, prefix, upstream):
    """Negative activation when the newest token is a side / wide / ideal word."""
    word = prefix.token_strings[-1].strip().lstrip("-.").lower()
    if word in BARE:
        value = -4.0
    elif word in STRONG or "理想" in word:
        value = -3.0
    elif word in MEDIUM or "侧" in word or "側" in word:
        value = -1.5
    elif word in WEAK:
        value = -0.7
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Control bytes and typography, modulated by recent text style.

NUL bytes get a large negative value, weaker near a document's beginning or
after spaces, numbers and punctuation. Tabs, padding, escaped newlines, table
bars and Markdown markers use recent Latin-word and code-syntax rates.
Invisible formatting is negative; percentages in prose are positive. Ordinary
tokens get zero. State resets at document boundaries. Individual word and
letter-specific activation differences are intentionally omitted.
"""
import math
import re
import unicodedata

READS = ()
CODE_WORDS = set('''def class import return public private protected static
void const let var function elif except catch
int float bool boolean string double char null None True False true false
package include namespace async await export print printf'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, pos, weight, syntax, words, capitals = '', 0, 0., 0., 0., 0.
    else:
        _, prev, pos, weight, syntax, words, capitals = carry
    s = prefix.token_strings[-1]
    text = s.strip()
    code_rate = syntax / max(weight, 1.)
    word_rate = words / max(weight, 1.)
    cap_rate = capitals / max(weight, 1.)
    plain = math.exp(-25. * code_rate)
    prose = plain * min(1., word_rate / .45)
    early = math.exp(-pos / 8.)
    leading = float(s.startswith(' '))
    value = 0.
    if '\x00' in s:
        value = -3.6 if pos == 0 else -5.0 + .8 * math.exp(-pos / 48.)
        if prev == ' ':
            value += 1.07
        elif prev.isspace():
            value += .70
        elif prev and prev[-1].isdigit():
            value += .51
        elif prev and not prev[-1].isalnum():
            value += .46
        elif prev.isupper():
            value -= .07
    elif s == '\\n':
        value = -.59 * plain - .67 * cap_rate + .13 * early
        if pos == 0:
            value = -.81
    elif '\t' in s:
        value = .08 - .25 * prose - .11 * cap_rate - .05 * min(4, s.count('\t'))
    elif s and s == ' ' * len(s) and len(s) >= 2:
        value = -.10 * prose + .10 * early
    elif '||' in s:
        value = -.50 - .64 * plain - .08 * prose + .26 * leading + .46 * early
    elif text in ('##', '###', '####', '#####', '######'):
        value = .12 - .26 * prose - .37 * cap_rate + .28 * early
    elif text in ('**', '*('):
        value = .06 - .16 * prose - .04 * leading + .26 * early
    elif '\x0c' in s:
        value = -.94
    elif any(unicodedata.category(c) == 'Cf' for c in s):
        value = -1.0 if '\u200e' in s or '\ufeff' in s else -.42
    elif text == '_':
        value = -.03 - .37 * prose - .39 * cap_rate + .16 * early
    elif text == '%':
        value = -.04 + .42 * prose - .09 * leading - .15 * early
    elif s and all(c == '\xa0' for c in s):
        value = .26 - .22 * plain - .31 * cap_rate + .09 * early

    is_code = (any(c in '{};=_' for c in s) or text in CODE_WORDS or
               re.search(r'[a-z][A-Z]|[a-z]_[a-z]', text) is not None)
    is_word = re.fullmatch(r' ?[A-Za-z]{2,}', s) is not None
    is_capital = bool(text) and text.isupper() and text.isalpha()
    state = (doc, s, pos + 1, .97 * weight + 1,
             .97 * syntax + is_code, .97 * words + is_word,
             .97 * capitals + is_capital)
    return state, float(value)

