"""Predict negative responses to damaged text and markup boundaries.

The main responses are to NUL bytes, doubled table pipes, escaped line
breaks, invalid UTF-8, and invisible direction or spacing marks.
Ordinary tokens receive zero.
"""

READS = ()

INVISIBLE_FORMAT_MARKS = {"\u200b", "\u200e"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if token == "\x00":
        return None, -4.75
    if token == "||":
        return None, -1.1
    if token == " ||":
        return None, -0.6
    if "||" in token:
        return None, -0.7
    if token == "\\n":
        return None, -0.66
    if "\ufffd" in token:
        return None, -0.75
    if token == "###":
        return None, -0.27
    if token == "##":
        return None, -0.48
    if any(mark in token for mark in INVISIBLE_FORMAT_MARKS):
        return None, -0.6
    if token == "\x0c":
        return None, -0.74
    return None, 0.0

