"""Layer-0 MLP component 421 (down_proj), a sparse "click / press" detector.

Its activation is mostly small and diffuse (RMS 0.036), but it is strongly negative on the
word that completes a UI "click ..." phrase or a "press|urized" word split. Examples seen in
the data: "click [here]" (-0.5 to -0.7), "@click [.option]" (-0.8), "press[ur]ized" (-0.8).
This program predicts those few cases and 0 everywhere else.
"""

READS = ()

CLICK = {"click", "clicks", "clicked", "clicking"}
PRESS_SPLIT = {"ur", "sed"}  # word pieces that continue "press" (pressurized, pressed)


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    prev = _word(prefix.token_strings[-2])
    cur = _word(prefix.token_strings[-1])
    if prev in CLICK:
        return None, (-0.55 if cur == "here" else -0.15)
    if prev == "press" and cur in PRESS_SPLIT:
