"""Detect the letter V/v, especially as a symbol or the start of a word.

Value, virtual, voltage, volume, vector, and version have stronger responses
than generic v-initial words.  Value/virtual/version also have Chinese forms.
A bare V/v is weaker inside a word than at a word boundary.  A check mark is
another V-shaped spelling that activates this detector.
"""
import string

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lstrip(string.punctuation)
    lower = word.lower()
    spaced = token.startswith(' ')
    reset = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if reset else prefix.token_strings[-2]
    inside_word = bool(previous and previous[-1].isalpha())
    value = 0.0

    if lower == 'v':
        capital = word == 'V'
        punctuation = raw[:-1]
        if spaced:
            value = 2.17 if capital else 1.19
        elif punctuation == '/':
            value = 2.1 if capital else 1.91
        elif punctuation == '-':
            value = 1.96 if capital else 1.62
        elif punctuation in ('.', '_'):
            value = 1.78 if capital else 1.40
        elif punctuation:
            value = 1.65 if capital else 0.97
        elif token.startswith('\t'):
            value = 1.80 if capital else 1.50
        elif reset:
            value = 3.18 if capital else 1.15
        elif inside_word:
            if capital:
                value = 1.04 if previous[-1].isupper() else 1.84
            else:
                value = 0.68
        else:
            value = 2.12 if capital else 1.12
    elif lower == 'value':
        if word.isupper():
            value = 1.20
        elif word[0].isupper():
            value = 1.58
        elif spaced:
            value = 1.44
        else:
            value = 1.24
    elif lower == 'values':
        if word.isupper():
            value = 0.60
        elif word[0].isupper() or spaced:
            value = 1.02
        else:
            value = 0.84
    elif lower == 'virtual':
        value = 2.34 if word[0].isupper() else (2.16 if spaced else 1.80)
    elif lower == 'voltage':
        value = 1.50
    elif lower in ('volt', 'volts'):
        value = 0.95
    elif lower.startswith('volum') or lower == 'vol':
        value = 0.88 if word[0].isupper() else 0.75
    elif lower.startswith(('vector', 'version')):
        value = 0.65 if word[0].isupper() else 0.58
    elif lower.startswith(('vertex', 'vertices')):
        value = 0.50 if lower.startswith('vertex') else 0.31
    elif 'Value' in word or 'VALUE' in word:
        value = 0.72
    elif word in ('值', '价值', '價值'):
        value = 1.17
    elif word in ('虚', '虚拟', '虛', '虛擬'):
        value = 2.05
    elif word in ('版', '版本'):
        value = 0.71
    elif word == '✓':
        value = 1.02 if spaced else 0.49
    elif word == '✔':
        value = 0.25
    elif lower.startswith('vaccin') or lower in ('virus', 'viruses', 'viral'):
        value = 0.64
    elif lower == 'veteran':
        value = 0.90
    elif lower in ('veterans', 'valuable'):
        value = 0.49
    elif lower in ('vs', 'versus'):
        value = 0.43
    elif word.isupper() and len(word) == 2 and 'V' in word and word != 'IV':
        value = 0.50
    elif lower.startswith('v'):
        if word[0].isupper():
            value = 0.30 if spaced or len(word) < 4 else 0.11
        else:
            value = 0.11 if spaced or len(word) < 4 else 0.04
    return None, float(value)

programs.luna:
"""Predict pulses on V-initial words, stronger for words beginning 'valu'."""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        in_word = starts_v = underscore_prefix = False
        word_head = ""
    else:
        _, in_word, starts_v, underscore_prefix, word_head = carry

    began_v = False
    uppercase_v = False
    saw_value_prefix = False
    for char in prefix.token_strings[-1]:
        if char == "_":
            if not in_word:
                in_word = True
                underscore_prefix = True
            elif not underscore_prefix:
                underscore_prefix = False
        elif char.isalnum():
            if not in_word:
                in_word = True
                starts_v = char.lower() == "v"
                word_head = char
                underscore_prefix = False
                if starts_v:
                    began_v = True
                    uppercase_v = char == "V"
            else:
                if len(word_head) < 4:
                    word_head += char
                if underscore_prefix and not starts_v:
                    starts_v = char.lower() == "v"
                    if starts_v:
                        word_head = char
                        began_v = True
                        uppercase_v = char == "V"
                    underscore_prefix = False
        else:
            in_word = starts_v = underscore_prefix = False
            word_head = ""
        if starts_v and word_head.lower().startswith("valu"):
            saw_value_prefix = True

    value_word = starts_v and word_head.lower().startswith("valu")
    if began_v:
        value = (1.3 if uppercase_v else 0.8) if saw_value_prefix else (
            0.8 if uppercase_v else 0.4
        )
    else:
        value = 0.35 if value_word else 0.0
    state = (doc, in_word, starts_v, underscore_prefix, word_head)
    return state, value

programs.sol:
"""Respond to angle-bracket syntax, especially the first name after '<'.

Markup names are strongest, closing names weaker, and type names intermediate.
A following '>' is negative when closing a just-introduced name.
The marker and name can occupy one token or two. Related opening syntax
(bracketed names, paths, LaTeX environments) receives smaller responses.
Special tool-call markers have separate strengths. Two previous tokens
provide context; their state resets at document boundaries. All weights are
approximate: these are syntax rules, not a table of vocabulary token IDs.
"""
import re

READS = ()

# Markup roles set the approximate response to an opening name.
MARKUP = (
    (5.0, 'summary param remarks exception example returns see seealso '
          'div tr html head body table section article header footer '
          'script style svg legend thead circle'),
    (4.6, 'input button label select option textarea fieldset details audio video'),
    (4.0, 'a span em td th font small ul dd dt tbody img meta time'),
    (3.5, 'b i u tt strong sub sup pre h title template ol'),
    (3.0, 'p li code'),
    (2.1, 'br'),
)
TAGS = {name: score for score, words in MARKUP for name in words.split()}
ROOTS = set('workspace usr var etc home tmp root opt bin lib src'.split())


def tag_score(name):
    return TAGS.get(name.lower() if name in {'FONT', 'CODE', 'PRE'} else name)


def signal(token, prev, before):
    s = token.strip()
    if s.startswith('<|') or s in {'<think>', '</think>', '</tool_call>', '</tool_response>'}:
        return 0.0
    if s in {'<tool_call>', '<tool_response>'}:
        return 1.27 if s == '<tool_call>' else 0.35
    if '<' in s and '<<' not in s and '<=' not in s:
        tail = s.rsplit('<', 1)[1]
        if tail.startswith('/'):
            return 0.28
        name = re.match(r'[^\W\d_]+', tail)
        if name:
            score = tag_score(name.group())
            return 2.6 if score is None else 1.1 * (score + 0.4)
        if tail.startswith(('!', '?', "'")):
            return 1.3
        if '\n' in token:
            return 0.65
        if prev.strip().isdigit():
            return 0.17
        if prev.isspace():
            return 1.9 if token.startswith(' ') and '\t' not in prev else 1.2
        return 0.77
    if prev.endswith('<') and not prev.endswith('<<'):
        if not token or token[0].isspace():
            return 0.0
        score = tag_score(s)
        if score is not None:
            value = score
        elif s.isdigit():
            value = 0.7
        elif s in {'file', 'filename', 'hostname', 'database'}:
            value = 3.9
        else:
            value = 1.7 if token[0].isalpha() else 1.1
            if token.istitle() and prev == '<':
                value = 1.0
        return value * (0.35 if prev.endswith(('\\<', '::<')) else 1.0)
    if prev.endswith(('</', '<\\/')):
        score = tag_score(s)
        return 1.05 if score is None else 0.36 * score
    if s.startswith(('>', '/>')) and not s.startswith('>='):
        if token.startswith(' '):
            return 0.52
        if (tag_score(prev) is not None or prev.startswith('<')
                or (before.endswith(('<', '</')) and prev.strip()[:1].isalpha())):
            return -0.4
        return 0.6 if s == '>' else 0.0
    if prev.endswith('/') and '<' not in prev and token and token[0].isalpha():
        return 0.6 if s in ROOTS else 0.13
    if token.startswith('[') and len(token) > 1 and token[1].isalpha():
        return 0.34
    if prev.endswith('[') and token and token[0].isalpha():
        return 0.13
    if (prev == 'begin' and s == '{') or (before == 'begin' and prev == '{'):
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    return (doc, token, prev), float(signal(token, prev, before))

programs.haiku:
"""Markup-tag detector: fires on the opening '<' of an HTML/XML/JSX tag and on the tag
name right after it (<td, <param, </code>), strongest for lowercase HTML tags, weaker for
capitalised component/type names, and ~0 for '<<', '<=', special tokens such as <|im_end|>."""

READS = ()
ROOTS = {"workspace", "usr", "tmp", "var", "home"}


def _name(s):
    s = s.strip()
    return len(s) > 0 and all(c.isalnum() or c in "_-:" for c in s)


def _opens(s):
    s = s.rstrip()
    return (s.endswith("<") or s.endswith("</")) and not s.endswith("<<")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    same = len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same else ""
    c = cur.strip()
    if _opens(prev) and _name(cur):
        if c[0].islower():
            return carry, 2.7
        if c[0].isupper():
            return carry, 1.0
        return carry, 0.0
    if _opens(cur) and c in ("<", "</"):
        if "\n" in prev:
            return carry, 0.6
        if prev[-1:].isalnum():
            return carry, 0.4
        return carry, 1.8
    if _opens(cur):
        return carry, 1.4
    if c.startswith("<") and len(c) > 1 and c[1].isalpha():
        return carry, 1.3
    if prev.strip() == "/" and c in ROOTS:
        return carry, 0.8
    return carry, 0.0

programs.luna:
"""A small cue for typed and tagged markup near an opening delimiter.

The strongest positive examples are names following an opening angle bracket,
as in HTML tags and generic types.  This is only a surface-text approximation.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()
    pos = prefix.position
    same_doc = (
        pos > 0
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    prev = prefix.token_strings[-2] if same_doc else ""
    before = (
        prefix.token_strings[-3]
        if pos > 1 and same_doc and prefix.document_ids[-2] == prefix.document_ids[-3]
        else ""
    )

    value = 0.0
    # Tool-protocol tags are different from ordinary tag and type names.
    protocol_tags = {
        "<tool_call>": 1.25,
        "<tool_response>": 0.35,
        "<think>": -0.2,
        "</think>": -0.2,
    }
    is_protocol_tag = text in protocol_tags
    if is_protocol_tag:
        value += protocol_tags[text]
    elif text == "<":
        value += 0.8
    elif text.startswith("<") and len(text) > 1 and text[1].isalpha():
        value += 2.5

    if prev.rstrip().endswith("<") and text and text[0].isalpha():
        value += 1.35
    if prev.rstrip().endswith("</") and text and text[0].isalpha():
        value += 0.8

    if not is_protocol_tag and (text == ">" or text.endswith(">")):
        value += 0.45
    if text.startswith("@") and len(text) > 1 and text[1].isalpha():
        value += 0.6

    if (
        prev.rstrip().endswith("\\begin{")
        or (prev.strip() == "{" and before.rstrip().endswith("\\begin"))
    ) and text and text[0].isalpha():
        value += 0.9
    if prev.rstrip().endswith("lt") and text.startswith(";"):
        value += 1.0

    if text == "workspace" and "/" in prev:
        value += 0.8
    return None, float(value)

