"""Creative-culture nouns: art, artworks, exhibitions, films, books, poems, architecture.

Layer-0 MLP feature (down_proj column 425). Its activation goes negative on words
for art and artistic works: "art" and "artwork" are strongest, then the arts and
their media (films, books, poems, paintings, installations, performances,
architecture, museums, galleries), then loose words like "work", "piece", "show".
Everywhere else it is near zero, so the program predicts 0 there.
"""

READS = ()

STRONG = {"art", "arts", "artwork", "artworks", "exhibition", "exhibit", "mediums", "paintings"}
MEDIUM = {
    "artist", "artists", "painting", "painter", "sculpt", "sculpture", "installation",
    "performance", "performances", "film", "films", "filmmakers", "book", "books",
    "poem", "poems", "poet", "novel", "fiction", "architecture", "architect",
    "architectural", "museum", "gallery", "galleries", "documentary", "photography",
    "illustration", "illustrations", "piece", "pieces", "works",
}
WEAK = {"work", "show", "form"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
