programs.sol:
"""A token-spelling approximation: per-, by, and percentage notation.

Bare per is strongest, especially after a boundary. Perfect and permission
are strong, percent and performance weaker; person and perhaps are exceptions.
A few Cyrillic spellings and Chinese equivalents are recognized too.
Everything else is zero. The previous token is used only for word boundaries
and the expression 'characterized by'; state resets at document boundaries.
"""
import string

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip(string.punctuation).lower()
    value = 0.0

    if word == 'by':
        value = 1.1 if text[:1] == 'B' else 0.77
        if prev.lower().endswith('characterized'):
            value = 0.2
    elif '%' in token or '％' in token:
        value = 0.91 if token in ('%', '％') else 0.65
        if token.endswith(('.', '\n\n')):
            value = 0.39
    elif word == 'per':
        value = 5.5
        if token == 'per':
            value = 3.3 if prev[-1:].isalnum() else 5.0
        elif token == 'Per':
            value = 6.2
        elif token == 'PER':
            value = 2.4 if prev[-1:].isalnum() else 5.5
        elif text.startswith('-'):
            value = 7.2
        elif text[:1] in '._/':
            value = 6.0
    elif 'perfect' in word:
        value = 3.6 if word == 'perfect' else 3.0
    elif word.startswith('permission'):
        value = 4.1 if word == 'permission' else 3.3
        if not token.startswith(' '):
            value -= 0.6
    elif word.startswith('percent'):
        value = 1.8 if not word.endswith('s') else 1.2
    elif word.startswith('perform'):
        value = 1.3 if word == 'performance' else 0.6
    elif word.startswith(('person', 'perhaps')):
        value = 0.0
    elif word in ('pero', 'però', 'perchè'):
        value = 0.3
    elif word.startswith('per'):
        value = 1.9 if len(word) <= 5 else 0.9
        if word.startswith('period'):
            value = 0.3
        elif word.startswith(('perce', 'permut')):
            value = 1.6
        elif word in ('perf', 'perfor', 'perpet'):
            value = 2.5
    elif word in ('imper', 'aper', 'iper'):
        value = 2.7
    elif word in ('hyper', 'super'):
        value = 0.75
    elif word == 'пер':
        value = 1.5 if token == 'пер' else 2.9
    elif word in ('透', '渗'):
        value = 3.4 if word == '透' else 1.9  # penetrate / permeate
    elif word.startswith('完美'):
        value = 3.7 if word == '完美' else 2.7  # perfect
    elif word in ('被', '每', '按', '极品'):
        value = 1.1  # by, each, according to, top-quality
    elif word in ('透过', '透過', '按照', '性能'):
        value = 0.65  # through, according to, performance
    return (doc, text), float(value)

