programs.sol:
"""Approximate a brief document-opening pulse, not a topic detector.

The pulse depends on the opening token's role: whitespace and ordinary
words are negative; digits and single capitals are weaker; some heading
and sentence separators are positive. English function words and source
file headers get separate broad averages. After three tokens the prediction
is almost zero, except for explicit chat, thought, and tool delimiters.
These rules deliberately omit word-specific and long-context variation.
"""
READS = ()

CONJUNCTIONS = set('and or but nor yet so'.split())
PREPOSITIONS = set('of in on at by from with without to for about into over '
                   'under through between among'.split())
COPULAS = set('be is are was were am been being'.split())
DETERMINERS = set('the this that these those'.split())
PRONOUNS = set('he she it they we you me him her them us'.split())
IMPORT_WORDS = {'import', 'using', 'package', 'namespace'}
DELIMITERS = {
    '<|im_start|>': 0.033,
    '<|endoftext|>': -0.015,
    '<tool_call>': 0.059,
    '<tool_response>': 0.118,
    '</tool_response>': -0.048,
    '<think>': -0.176,
    '</think>': -0.105,
}
CHAT_ROLES = {'user': -0.387, 'assistant': -0.473, 'system': -0.609}


def opening_value(s):
    z = s.strip()
    spaced = s.startswith(' ')
    if s == '<|im_start|>':
        return -0.874
    if not z:
        if s.count('\n') >= 2:
            return -0.33
        if '\n' in s:
            return -0.50
        return -0.27 if '\t' in s else -0.37
    if s == 'Title':
        return 0.812
    if s == '<?':
        return 0.366
    if s.startswith('#!'):
        return 0.125
    if s == '#':
        return 0.299
    if s in {'##', '###'}:
        return 0.07
    if s.startswith('#'):
        return -0.17
    if s == ',':
        return 0.269
    if s == '.':
        return 0.160
    if s in {'，', '。'}:
        return 0.10
    if s in {':', ';', '?', '：'}:
        return -0.04
    if s == '//\n':
        return 0.420
    if s in {'//', '/*'}:
        return -0.06
    if z.isdecimal():
        return -0.118
    if all(not c.isalnum() for c in z):
        if s[0] in '()[]':
            return -0.12
        if s[0] in '-_*':
            return -0.47
        if '\n' in s:
            return -0.23
        return -0.24
    if len(z) == 1 and z.isascii() and z.isalpha():
        if z.isupper():
            return -0.12 if spaced else -0.024
        return -0.236 if spaced else -0.153
    word = z.lower()
    if s in IMPORT_WORDS:
        return -0.06
    if spaced and word in CONJUNCTIONS:
        return -0.05
    if spaced and word in PREPOSITIONS | COPULAS:
        return -0.15
    if spaced and word in {'a', 'an'}:
        return -0.37
    if word in DETERMINERS:
        if spaced and z.istitle():
            return -0.60
        return -0.27 if spaced else -0.23
    if word in PRONOUNS:
        return -0.21
    if z.isascii() and z.istitle():
        return -0.31
    return -0.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, 0, s), float(opening_value(s))
    _, position, first = carry
    position += 1
    if first == '<|im_start|>' and position == 1:
        value = CHAT_ROLES.get(s, -0.40)
    elif first == '<|im_start|>' and position == 2:
        value = 0.037
    elif s in DELIMITERS:
        value = DELIMITERS[s]
        if s == '<think>' and position <= 3:
            value = -0.378
    else:
        value = -0.001 if position > 3 else (0., -0.051, -0.020, -0.010)[position]
    return (doc, position, first), float(value)

