"""Layer-0 MLP down_proj component 432: it fires negatively on words that introduce a list of
what is included or an example of something. Strongest on "including" (and "include",
"includes", "included", "包括"); moderate on "such as", "for example", "for instance",
"in particular", "e.g."; weak on verbs and phrases of composition ("comprising",
"consisting of", "involving", "featuring", "containing"). All other tokens predict 0."""

READS = ()

INCLUDING = {"including", "包括", "incl", "cluding", "включая", "포함", "incluindo"}
INCLUDE_VERB = {"include", "includes", "included", "includ", "inclusion"}
EXAMPLE_INTRO = {"例如", "比如", "如", "notamment", "namely", "especially", "particularly"}
COMPOSITION = {"comprising", "comprises", "comprise", "involving", "involves", "featuring",
               "containing", "contains", "consisting", "consists"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" .\n").lower()
    prev = prefix.token_strings[-2].strip(" .\n").lower() if len(prefix) > 1 else ""
    if word in INCLUDING:
        value = -6.0
    elif word in INCLUDE_VERB:
        value = -3.0
    elif word == "as" and prev == "such":
        value = -2.0
    elif word == "such":
        value = -0.3
    elif word in ("example", "instance") and prev == "for":
        value = -1.2
    elif word == "particular" and prev == "in":
        value = -1.0
    elif word == "g" and prefix.token_strings[-1].startswith("."):
        value = -1.0
    elif word in EXAMPLE_INTRO:
        value = -1.0
    elif word in COMPOSITION:
        value = -0.7
    elif word == "of" and prev in ("consisting", "consist", "consists", "consisted", "inclusion"):
        value = -0.8
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Mostly a lexical crossing signal, rather than a general spatial reasoner.

Cross/across and their inflections dominate; passage and containment words
are weaker; a few forms distinguish letter case. Chinese crossing characters
and a few translated passage stems also fire. Gross and unspaced 'ross' are spelling echoes. Keep one token of
history for split words and the immediate continuation of crossing phrases.
"""

READS = ()

CROSS_WORDS = {
    'cross': 7.3, 'across': 6.65, 'crossing': 5.3, 'crossed': 5.1,
    'crosses': 5.25, 'crossings': 4.55, 'crossword': 4.7, 'crossover': 1.25,
    'Cross': 7.7, 'CROSS': 5.6, 'Across': 6.0, 'Crossing': 4.0,
}
PASSAGE_WORDS = {
    'through': 0.7, 'throughout': 0.71, 'within': 0.59, 'inside': 0.55,
    'outside': 0.37, 'against': 0.24, 'via': 0.23, 'along': 0.19,
    'bridge': 0.48, 'trans': 1.25, 'travers': 0.77, 'traverse': 0.55,
    'traversal': 0.39, 'través': 1.55, 'atrav': 1.5, 'attravers': 1.45,
    'عبر': 2.0, 'через': 0.34, 'пер': 0.63, 'cruz': 2.2, 'Cruz': 0.73,
}
CROSSING_CHARACTERS = {
    '跨': 7.3, '横': 3.9, '橫': 3.9, '交叉': 4.35, '十字': 3.4,
    '交': 0.88, '渡': 1.2, '穿越': 1.33, '越': 0.57,
}


def lexical_value(token):
    raw = token.strip()
    word = raw.lower()
    if raw in CROSS_WORDS:
        return CROSS_WORDS[raw]
    if raw in PASSAGE_WORDS:
        return PASSAGE_WORDS[raw]
    if word in CROSS_WORDS:
        return CROSS_WORDS[word]
    if word in PASSAGE_WORDS:
        return PASSAGE_WORDS[word]
    if word in CROSSING_CHARACTERS:
        return CROSSING_CHARACTERS[word]
    if word.startswith('跨'):
        return 7.3 / len(word) ** 1.3
    if word.startswith('intersect'):
        return 0.7
    if word in {'-cross', '_cross', '.cross'}:
        return 7.7 if word[0] == '-' else 5.3
    if word == '-through':
        return 0.64
    if word in {'gross', 'grosse'}:
        return 2.3 if word == 'gross' else 1.2
    # Unspaced fragments, deliberately excluding the surname 'Ross'.
    if token in {'ross', 'ROSS', 'rosse'}:
        return {'ross': 4.0, 'ROSS': 5.4, 'rosse': 2.2}[token]
    if word == 'росс':
        return 2.8
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = lexical_value(token)

    # A multi-byte character may only become readable at its last token.
    if '\ufffd' in token:
        last_character = prefix.text_prefixes[-1][-1:]
        value = CROSSING_CHARACTERS.get(last_character, value)

    root = previous.lstrip('-_.')
    if token in {'ross', 'ROSS'} and previous.endswith('c'):
        value = 6.4
    elif root in {'cross', 'ross'} and token.lower() in {'ed', 'ing'}:
        value = 5.3 if root == 'cross' else 2.55
    elif previous == 'trans' and token.lower() in {'verse', 'vers'}:
        value = 1.0 if word == 'verse' else 0.54
    elif root in {'cross', 'across', 'crossed', 'crosses',
                  'crossing', 'crossings'}:
        if word == 'the':
            value = 1.45 if root == 'cross' else 0.9
        elif word in {'a', 'an', 'this'}:
            value = 0.48
        elif word == 'of' and root in {'cross', 'crossing', 'crossings'}:
            value = 3.4 if root == 'cross' else 1.9
        elif word == 'over':
            value = 1.4
        elif root == 'cross' and token.lower() in {'word', 'words', 'roads'}:
            value = {'word': 5.8, 'words': 3.55, 'roads': 1.65}[word]
        elif root == 'cross' and word in {'section', '-section'}:
            value = 0.5
    return (doc, word), value

