programs.sol:
"""A lexical detector of interiors and containment, with negative output.

The strongest cues are Chinese/Japanese 内 (traditional 內) and Korean 내,
all meaning 'inside/internal'. English inner, internal, within, and their
translations give smaller negative signals. Contents, domesticity, and
related code identifiers are weaker cues. The constants approximate training
averages; spelling, capitalization and token boundaries affect strength.
Unlisted tokens receive zero, leaving small unrelated fluctuations unexplained.
This does not track actual locations or infer whether a sentence describes
containment. The only use of preceding text is to decode split UTF-8 bytes.
"""
READS = ()


def lexical_value(text):
    s = text.strip()
    w = s.lower().lstrip('._/(-')
    spaced = text.startswith(' ')
    capital = bool(s) and s[0].isupper()
    # East Asian interior words and compounds.
    if s in {'内', '內'}:
        return -8.3
    if s == '내':
        return -7.7 if spaced else -6.7
    # Within a limit; within a country/body/group/time interval.
    if s == '以内':
        return -7.8
    if s in {'国内', '國內', '内的', '内の', '体内', '党内', '日内', '之内'}:
        return -6.5
    # Indoors, inside a shop.
    if s in {'室内', '店内'}:
        return -4.2
    if s in {'国内外', '内外', '内で'}:
        return -4.8
    if s.endswith(('内容', '內容')):
        return -1.3 if len(s) == 2 else -0.8
    # 内 used as a 'within' suffix; longer compounds are attenuated.
    if s.endswith(('内', '內')):
        return -max(3.8, 6.0 - 0.6 * (len(s) - 2))
    if s.startswith(('内', '內')):
        if s in {'内部', '內部'}:
            return -3.4
        if s in {'内容', '內容', '内存', '内阁'}:
            return -1.3
        return -2.2
    if '内' in s or '內' in s:
        return -2.8
    # Other forms of 'in/inside', and the weaker exterior counterpart.
    if s in {'里', '裡'}:
        return -1.0
    if s == '裏':
        return -0.7
    if s.startswith(('里面', '裡面')) or s in {'子里', '村里'}:
        return -2.0
    if s in {'里的', '家里', '在家里', '店里', '眼里', '房间里'}:
        return -1.2
    if s in {'外', '期间', '안'}:
        return -1.2
    if s == '室' or s == '외':
        return -0.6
    # English words, allowing common identifier punctuation.
    if w == 'within':
        return -2.7 - 0.25 * capital + 0.3 * (not spaced)
    if w == 'inner':
        return -3.7 if spaced and not capital else -2.6
    if w == 'internal':
        if s.startswith('/'):
            return -1.9
        if s.startswith('.') and not capital:
            return -4.0
        return -3.4 if spaced and not capital else -2.9
    if w == 'inline':
        return -2.5
    if w in {'inside', 'internally', 'internals', 'interior', 'interiors'}:
        return -2.0
    if w in {'domestic', 'indoor', 'indoors'}:
        return -1.7
    if w in {'intra', 'intr', 'intern', 'intrinsic', 'inward', 'inland', 'infield'}:
        return -1.15
    if w in {'inherent', 'insider', 'insiders'}:
        return -0.6
    if w == 'innerhtml':
        return -1.5 if s.startswith('.') else -2.3
    if w in {'innertext', 'innerwidth', 'innerheight'}:
        return -0.6
    if w == 'content':
        return -0.06 if spaced and not capital else -0.4
    if w in {'contents', 'builtin', 'uiltin', 'wherein', 'herein'}:
        return -0.5
    if w in {'external', 'outer', 'outdoor', 'outdoors'}:
        return -0.25
    # Russian 'internal' stem; Vietnamese 'internal'.
    if s in {'внут', 'nội', 'Nội'}:
        return -3.5
    # Russian, Spanish/Portuguese, Dutch: 'inside/within'.
    if s in {'внутри', 'dentro', 'binnen'}:
        return -2.7
    # Korean 'domestic'; Thai 'within'.
    if s in {'국내', 'ภายใน'}:
        return -4.5
    # Arabic and Turkish 'inside'; Thai 'in'; Korean 'content'.
    if s in {'داخل', 'içinde'}:
        return -1.9
    if s in {'iç', 'ใน', '내용'}:
        return -1.3
    # Japanese/Chinese 'in/among'; Indonesian/Vietnamese 'in'.
    if s in {'の中', 'の中で', '之中', '家中'}:
        return -0.8
    if s in {'dalam', 'trong'}:
        return -0.45
    if s == 'خلال':
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-2] == prefix.document_ids[-1])
    if '\ufffd' in text and same_document:
        # A byte fragment can finish a Chinese interior character.
        assembled = prefix.text_prefixes[-1][-1:]
        if assembled in {'内', '內'}:
            return None, -10.3
    return None, lexical_value(text)

programs.haiku:
"""Inside / within / internal detector (negative activation).

Layer-0 MLP feature that goes strongly negative on words meaning "inside,
within, internal" in English and other languages, most strongly the CJK
character 内 (and 內), which means "inside / within" in words such as
国内 (domestic), 以内 (within), 体内 (inside the body).
It is near zero everywhere else. The program looks only at the text
completed by the current token (so a character split over several byte
tokens counts where it completes) and returns a fixed value per word class.
"""

READS = ()

# English / other-language words for "inside / within / internal"
WORDS = {
    "internal": -3.0, "internally": -1.9, "inner": -3.0, "within": -2.8,
    "inline": -2.6, "interior": -2.0, "interiors": -1.8, "inside": -1.9,
    "indoor": -1.6, "indoors": -1.6, "inward": -1.2, "intrinsic": -1.3,
    "intra": -1.0, "intr": -1.0, "intern": -1.1, "internals": -2.2,
    "innen": -0.9, "domestic": -1.8, "внут": -3.7, "внутри": -2.5,
    "dentro": -2.9, "nội": -4.3, "داخل": -2.1,
}

# 内 words whose meaning is not "inside": content, memory, cabinet, connotation
NOT_INSIDE = ("内容", "內容", "内存", "内阁", "内涵", "内心", "内衣")


def completed(prefix):
    """The text this token completes: the new characters of the decoded prefix."""
    cur = prefix.text_prefixes[-1]
    prev = "" if prefix.position == 0 else prefix.text_prefixes[-2].rstrip("�")
    if cur.startswith(prev):
        cur = cur[len(prev):]
    return cur.replace("�", "")


def step(carry, prefix, upstream):
    s = completed(prefix)
    word = "".join(ch for ch in s.lower() if ch.isalpha())
    if s.strip() in ("内", "內"):
        return carry, -8.3  # the bare character: inside, within
    if s.strip() in ("内部", "內部"):
        return carry, -3.5  # internal (part)
    if any(w in s for w in NOT_INSIDE):
        return carry, -1.3  # 内容 "content" etc.: not a locative 内
    if "内" in s or "內" in s:
        return carry, -6.0  # 国内 domestic, 以内 within, 体内 inside the body
    if "내" in s:
        return carry, -6.0  # Korean 내 (inside), 국내 (domestic)
    if s.strip() in ("里面", "裡面"):
        return carry, -1.9  # inside (place)
    return carry, WORDS.get(word, 0.0)

