"""A sparse negative cue for interior, inside, and within language.

The inside characters 内/內 are strongest. English and other-language words
for within/inside get graded values; unrelated text is left at zero.
"""

READS = ()

CHINESE_STRONG = frozenset("内內")
CHINESE_MILD = frozenset("里裏室外")
WORD_VALUES = (
    ("internally", -1.9),
    ("within", -2.6), ("inner", -3.1), ("internal", -3.2),
    ("indoor", -1.5), ("interior", -2.2), ("inside", -2.0),
    ("intra", -1.0), ("inward", -0.6),
    ("wherein", -0.6), ("therein", -0.6), ("herein", -0.6),
    ("content", -0.6), ("builtin", -0.6), ("built-in", -0.6),
)
OUTSIDE_WORDS = ("external", "outside", "outer", "outdoor", "outdoors")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if word in CHINESE_STRONG:
        return None, -8.0
    if word in CHINESE_MILD:
        return None, -1.4
    if word == "内涵":
        return None, -1.8
    if word in ("期间", "期間", "国产", "本站", "本周"):
        return None, -0.7
    if word == "안":
        return None, -1.2
    if word == "dalam":
        return None, -0.6
    if word.startswith("внут"):
        return None, -3.8
    for cue, value in WORD_VALUES:
        if cue in word:
            return None, value
    if word in OUTSIDE_WORDS:
        return None, -1.0
    return None, 0.0

