"""layers.0.mlp.down_proj:436 -- a "field label colon" detector.

This component goes negative on a colon that follows a field label: the colon in
"Date: ...", "Joined: ...", "name": ..., "command: ...". It is strongest after a
metadata or record field name (Date, Location, Joined, Posts, name, type, command,
path, ...), a little weaker after other capitalised or lower-case words, and close to
zero after a digit (a time like 10:30, a numbered list) or after words such as
"following". Everywhere that is not a colon it is near zero.

The program: if the current token ends in a colon, look at the word before it and
return a negative value graded by how label-like that word is. Otherwise return 0.
"""

READS = ()

# Field names of records, profiles and config/JSON-style key-value lines.
FIELD_NAMES = {
    "Date", "Location", "Joined", "Posts", "Author", "Source", "Subject", "Views",
    "Type", "Name", "name", "type", "description", "command", "path", "arguments",
    "Time", "Input", "Output", "Value", "Cost", "Description", "Explanation", "email",
}


def strength(word):
    """How negative the activation is, given the word before the colon."""
    if word == "" or word.isdigit():
        return 0.0            # 10:30, "1:" list numbers: no response
    if word in FIELD_NAMES:
        return -2.0           # a known field label
    if word[:1].isupper():
        return -0.7           # a capitalised label, e.g. "Recommendation:"
    if word.isalpha():
        return -0.35          # an ordinary lower-case word
    return -0.4


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].rstrip(" \n")
    if not cur.endswith((":", "：")) or cur.endswith("::") or len(prefix.token_strings) < 2:
        return None, 0.0
    if cur.endswith(('":', "':")):
        return None, -1.5     # a JSON-style key closing quote followed by colon
    return None, strength(prefix.token_strings[-2].strip())


if __name__ == "__main__":
    # Quick check on a few hand-made lines: label colons should be negative.
    for line in ["Date: 2020", "It starts at 10:30", "name: x"]:
        print(line, step(None, type("P", (), {"token_strings": [line.split(":")[0], ":"]})(), {})[1])

