"""Language-sensitive sentence punctuation, especially periods.

Recognize language context from common function words and Unicode scripts.
Older words count less. Predict strong positive periods in non-English
alphabetic prose, weaker ones after digits or at line/paragraph endings.
English and Chinese/Japanese context gives little response. Questions and
exclamations are weaker than periods; hyphens have the opposite sign.
Unmodelled tokens get zero.
"""
import unicodedata

READS = ()
ENGLISH_FUNCTION_WORDS = frozenset('''
the and of to is that it for with on this be are was by
from or an have has not but at you we they he she will can which would his her
their there been were than if all also more into its our these such one about
when what who how any then each them other only out some your as'''.split())
FOREIGN_FUNCTION_WORDS = frozenset('''
de la en el le les un une des du et est dans au aux il
qui sur se ce pas plus sont ne que por para los las del con una che di gli
della per non sono der die das und ist zu mit den von im sich nicht ein eine
auch dem wird des als es um uma os dos não com na em é ao nos este esta sua
ele ela mais een van het niet op voor zijn och att det är för til som på med
er og af den het wat maar naar om nog te za jest nie się oraz do jak dla
się și în cu pentru din este sunt az hogy egy nem vagy da je na se za u
som ja ett av ikke fra har wir sie bei werden durch nach o e'''.split())


def word_cue(word):
    """Low-response evidence, foreign alphabetic evidence, and its strength."""
    word = word.lower()
    if word in ENGLISH_FUNCTION_WORDS:
        return (1.0, 0.0, 0.0)
    letters = [c for c in word if c.isalpha() and ord(c) > 127]
    if letters:
        script = unicodedata.name(letters[0], '').split()[0]
        if script in {'CJK', 'HIRAGANA', 'KATAKANA'}:
            return (1.0, 0.0, 0.0)
        strength = {'CYRILLIC': 1.8, 'ARABIC': 1.05,
                    'GREEK': 1.35, 'HANGUL': 0.85}.get(script, 1.35)
        return (0.0, 1.0, strength)
    if word in FOREIGN_FUNCTION_WORDS:
        weight = 0.2 if len(word) == 1 else 1.0
        return (0.0, weight, weight * 1.35)
    return (0.0, 0.0, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, 0.0, 0.0, '')
    _, word, low, foreign, strength, previous = carry
    token = prefix.token_strings[-1]
    for c in token:
        if c.isalpha():
            word += c
        elif word:
            cue = word_cue(word)
            # Each completed word discounts older evidence by six percent.
            low = 0.94 * low + cue[0]
            foreign = 0.94 * foreign + cue[1]
            strength = 0.94 * strength + cue[2]
            word = ''
