            scale *= 0.55
        value = -0.015 + scale * language
    elif token.strip() in {'?', '!'}:
        value = -0.03 + 0.6 * language
    elif token.strip() == '-':
        value = 0.05 - 0.24 * language
        if '\n' in token:
            value -= 0.15
