    elif word in {'сум', 'suma', 'summa'} or word.startswith('сумм'):
        value = 4.4 if word == 'сум' else 3.3
    elif word in {'总', '總', '总数', '积', '積'}:
        value = 1.1
    elif word == '总结':
        value = 2.1
    elif word in {'加', '差', '합'}:
        value = 0.6

    prior_word = word_part(previous).lower()
