SUM_SIGNS = {"Σ", "∑"}
SUM_FAMILY = {"summ", "summar", "summary", "summarize", "summer", "summit"}
AGGREGATE_WORDS = {"total", "count", "counts", "counting", "product", "difference",
                   "average", "mean", "integral"}


