"""Local responses to asterisks, code markers, and marker transitions.

The main positive responses are on an asterisk and on the next token, especially
'* @' documentation tags. Double underscores similarly boost following names
or numbers. Repeated backticks/dollar signs are negative. Nearby repetitions,
comment openings, whitespace, and document starts modify these responses.
Unrecognized text is predicted as zero. This is a marker approximation, not a
claim that every word-dependent variation of the component is explained.
"""
import re

READS = ()
DOCUMENTATION_HEADINGS = {'Copyright', 'Licensed', 'Created', 'Author'}
PYTHON_SPECIAL_NAMES = set('''
init new del repr str bytes format hash bool getattribute getattr setattr delattr
get set delete set_name call len length_hint getitem setitem delitem missing
iter next reversed contains add sub mul matmul truediv floordiv mod divmod pow
neg pos abs invert complex int float index round enter exit await aiter anext
class dict doc module name qualname bases mro slots all file version
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, history = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    s, p = token.strip(), previous.strip()
    spaced = token.startswith(' ')
    newline = '\n' in token or '\r' in token
    after_star = p.endswith('*') and '\n' not in previous and '\r' not in previous
    value = 0.0

    if not any(c in s for c in '*@_`$'):
        if after_star:
            value = 0.65 + 0.55 * s.isdecimal() - 0.4 * newline
            value -= 0.15 * (spaced and s.isalpha())
            value += 2.8 * (s in DOCUMENTATION_HEADINGS)
        elif p.endswith('__') and len(p) < 5:
            value = 0.52 + 0.48 * s.isdecimal()
            value += 0.6 * (s in PYTHON_SPECIAL_NAMES)
            value -= 0.22 * spaced + 0.3 * p.startswith('/')
        elif p.endswith('$'):
            value = 0.13 + 0.4 * s.isdecimal() - 0.08 * spaced
        elif s.isdecimal() and p in {'£', '€', '¥', '₹', '₽', '₩'}:
            value = 0.22
        elif p in {'#', '##', '###', '//', '///'}:
            value = 0.12
        elif '*' in p and p.endswith(('(', '(-')):
            value = 0.4

    stars = s.count('*')
    if stars and '/' not in s:
        if stars == 1:
            value = 1.05 + 0.2 * spaced
            value -= 0.2 * (not previous or previous.isspace())
            value -= 0.4 * s.endswith((')', ',', ';')) + 0.25 * newline
            value -= 0.55 * bool(re.search(r'/\*+\s*$', history))
            value -= 1.5 if after_star else 0.65 * ('*' in p)
            if s == '*' and '*' in p and (newline or '\n' in previous):
                value = 0.1 if spaced else -0.1
        elif stars == 2:
            value = 0.7 + 0.25 * spaced
            value -= 1.0 if '*' in p else 0.35 * ('*' in history[-12:])
            value -= 0.4 * s.endswith((',', ')', ':', ';'))
        else:
            value = 0.5
    elif '/*' in s:
        value = -0.1
    elif '*/' in s:
        value = 0.1
    elif '@' in s:
        value = 0.72 if s == '@' else 0.3
        if token == ' @' and (after_star or p.endswith('///')):
            value = 3.45 if after_star else 1.8
    elif s == '_':
        value = 0.28 if spaced else 0.1
    elif s.endswith('._'):
        value = 0.58
    elif s == '__':
        value = 0.24 if spaced else -0.13
    elif '`' in s:
        value = -0.05 - 0.1 * newline
        if not newline:
            value -= 0.75 * p.endswith('`') + 0.3 * after_star
    elif '$' in s:
        value = -1.1 if p.endswith('$') else 0.06 * spaced

    if first:
        if s in ('*', '**', '_', '__'):
            value = {'*': -0.5, '**': -5.3, '_': -0.8, '__': -2.0}[s]
        elif s in ('`', '``', '```'):
            value = -0.65 if spaced else (-2.8 if len(s) == 3 else -2.0)
        elif s and set(s) == {'$'}:
            value = -1.25 if spaced else -2.15
        elif s.startswith('/*') and stars <= 3:
            value = -0.8

    return (doc, token, (history + token)[-64:]), float(value)

