"""Asterisk and at-sign detector for one down-projection direction.

Fires on symbols that open a comment or markup line:
  * " @" starting a javadoc/phpdoc tag (" * @param", " * @return"): strongest, about 3.5;
  * a bare "@" (email addresses, MathType markup): about 0.5;
  * star symbols: a comment-line " *", a lone "*" (markdown emphasis, multiplication),
    "**", ")*", "*(": about 1.0;
  * a version digit right after a "__" in a repo path ("owner__repo__1.0"): about 0.9.
Backtick code quotes push slightly negative (about -0.4). Everything else is about zero.
"""
READS = ()

STARS = {"*", " *", "**", " **", "*(", ")*", "*.", "]*", "*/"}
BACKTICKS = {" `", "``", " ``", "`"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok == " @":
        return None, 3.5
    if tok == "@":
        return None, 0.5
    if tok in STARS:
        return None, 1.0
    if tok.isdigit() and prev.endswith("__"):
        return None, 0.9
    if tok in BACKTICKS:
        return None, -0.4
    return None, 0.0

