READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or prefix.document_ids[-2] != doc:
        history = ""
    else:
        history = carry

    score = 0.0
    has_star = "*" in token
    in_doc_comment = history.rfind("/**") > history.rfind("*/")

    if has_star:
        score += 0.75
        if any(ch.isalnum() for ch in token):
            score += 0.33
        if in_doc_comment:
            score -= 0.37
    if "@" in token:
        score += 0.48
        if in_doc_comment and "*" in history[-12:]:
            score += 3.27

    if token.strip() in {"_", "._"}:
        score += 0.7
    elif token.count("_") >= 4:
        score -= 1.0
    elif token.count("_") > 1:
        score -= 0.13

    # In some formatted code examples, a closing backtick is followed by a
    # spaced opening backtick between inline spans.
    if "`" in token and history.endswith("`"):
        score -= 0.8
    if "$" in token and history.rstrip().endswith("$"):
        score -= 1.2
    if "##" in token and not history:
        score -= 0.8
    if history.rstrip().endswith("**") and token.strip().isdigit():
        score += 1.2

    new_history = (history + token)[-400:]
    return new_history, float(score)

