"""Spot technical text cues (TeX, math words, bars, URLs, and code markers).

These cues often accompany positive activations. Hand-set scores give a rough
estimate, shrunk to avoid overpredicting when a cue appears in ordinary text.
"""
READS = ()

TEX_COMMANDS = {
    "frac": 12.4,
    "cite": 2.2,
    "begin": 2.0,
    "left": 2.3,
    "text": 3.0,
}
MATH_WORDS = {
    "numerator": 1.0,
    "denominator": 0.46,
    "ratio": 0.72,
    "symbol": 1.1,
    "stack": 0.6,
    "sqrt": 0.6,
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]

    def earlier(offset):
        i = len(prefix) - 1 - offset
        if i < 0 or prefix.document_ids[i] != doc:
            return ""
        return prefix.token_strings[i].strip()

    previous = earlier(1)
    before_previous = earlier(2)
    third_previous = earlier(3)
    value = MATH_WORDS.get(word, 0.0)

    # TeX commands are recognizable by their leading backslash.
    if previous.endswith("\\") and word in TEX_COMMANDS:
        value = TEX_COMMANDS[word]
    if word == "{" and previous == "begin":
        value = 1.1
    if word.endswith("atrix") and previous.startswith("pm"):
        if before_previous == "{" and third_previous == "begin":
            value = 1.8
    if word == "}" and previous.endswith("atrix"):
        value = 0.6
    if word == "symbol" and previous == "bold":
        value = 1.1
    if word == "_{":
        value = 0.3

    # Bars often separate columns or mathematical cases.
    if word == "|":
        value = 0.82

    # A URL scheme and its following host-name pieces.
    url_age = carry[1] + 1 if carry and carry[0] == doc else 0
    if word.endswith("://"):
        value = 4.7
        url_age = 0
    elif word.endswith(".com"):
        value = max(value, 1.1)
    elif 0 < url_age <= 3 and word:
        value = max(value, 1.0)

    # Familiar programming names and annotations.
    if word == "param" and previous == "@":
        value = 0.56
    if word == "Override" and previous == "@":
        value = 0.8
    if word == "init" and previous == "__":
        value = 0.86
    if previous == "init" and word.startswith("__("):
        value = max(value, 0.9)
    if word == "self" and previous.startswith("__(") and before_previous == "init":
        value = max(value, 0.34)
