"""A short-range English subject/auxiliary detector.

Pronoun contractions and existential 'there is/are' give large responses;
most capitalized subjects receive stronger responses than lowercase ones.
Possessive apostrophe-s does not. Smaller rules cover introductory reference
phrases and existential auxiliary chains. Capitalization, token separation,
and apostrophe style adjust the response. Strengths are rounded training
averages; the rules omit most small, word-specific background activations.
The state resets at document boundaries.
"""
READS = ()
PERSONAL = set('i you we they he she it who'.split())
SHORT = {'m': 1.4, 're': 1.7, 've': 1.6, 'd': 1.35, 'll': 1.15}
BE = {'is': 1.7, 'are': 1.25, 'was': 1.45, 'were': 1.15}
AUXILIARIES = set('can could will would should may might must have has had'.split())
CHAIN = AUXILIARIES | set(
    'is are was were be been to seem seems appear appears'.split()
)
CHAIN |= set('not only also never already probably really just'.split())
CHAIN |= {"'s", '’s', "'t", '’t'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry and carry[0] == doc:
        _, previous, existential, age = carry
    else:
        previous, existential, age = '', None, 0
    token = prefix.token_strings[-1]
    host = previous.lstrip(' \t\r\n\"\'“‘([{>.…#')
    h = host.lower()
    upper = host[:1].isupper() and h != 'i'
    separate = not previous[:1].isspace()
    s = token.replace('’', "'")
    w = token.strip().lower()
    value = 0.0
    if s == "'s" and h in {'it', 'he', 'she', 'who', 'there', 'here', 'that', 'what'}:
        value = 3.65 if h == 'there' else 2.45 if h == 'what' else 2.1
        bonus = .85 if h in {'there', 'here', 'it'} else .5 if h == 'that' else .1
        value += upper * bonus + .25 * (separate and h in {'there', 'here', 'that'})
        value += (.10 if upper else .20) * token.startswith('’')
    elif s[:1] == "'" and s[1:] in SHORT and h in PERSONAL:
        suffix = s[1:]
        if suffix != 'm' or h == 'i':
            value = SHORT[suffix] + .2 * (h in {'we', 'they', 'he', 'she'})
            value += upper * (.65 if h in {'you', 'it'} else .35)
            value += (.3 if suffix == 'm' else .1) * token.startswith('’')
    elif token[:1].isspace():
        if h == 'there' and w in BE:
            value = BE[w] + .67 * upper + .22 * separate
        elif h == 'there' and w in {'be', 'been', 'exists', 'exist'}:
            value = (1.25 if w == 'be' else .55 if w == 'exist' else 1.0)
            value += .5 * upper
        elif w in BE and h in PERSONAL | {'this', 'that', 'here', 'these', 'those'}:
            base = 0.
            if h in {'it', 'this'}:
                base = .28
            elif h == 'here':
                base = .4
            elif h in {'that', 'they', 'these', 'those'}:
                base = .1
            bonus = .15
            if h in {'you', 'here'}:
                bonus = .7
            elif h in {'it', 'this', 'that'}:
                bonus = .5
            elif h in {'we', 'they', 'these', 'those'}:
                bonus = .33
            value = base + upper * bonus + .15 * (separate and h != 'i')
        elif w in AUXILIARIES and h == 'there':
            value = .3 + .65 * upper + .2 * separate
        elif w in AUXILIARIES and h in PERSONAL | {'this', 'that'}:
            value = -.03 + .10 * (h in {'you', 'we'})
            if upper:
                value += .5 if h in {'it', 'you'} else .35
                value += .2 * (w == 'can') + .12 * separate
        elif h in {'the', 'this', 'your'} and upper and w.isalpha():
            value = (1.15 if w == 'following' else .12) + .16 * separate
        elif h == 'for' and w in {'example', 'instance'}:
            value = .4 + .45 * upper
        else:
            value = -.006 if w.isascii() and w.isalpha() else 0.
    # The subject survives an auxiliary chain: 'there should have been'.
    if (existential is not None and w in {'be', 'been'}
            and token[:1].isspace() and age < 8):
        value = (1.15 if w == 'be' else .97) + .4 * existential
    if w == 'there':
        existential, age = token.strip()[:1].isupper(), 0
    elif w in CHAIN and age < 8:
        age += 1
    else:
        existential = None
    return (doc, token, existential, age), float(value)

