"""Verb-after-subject detector for layers.0.mlp.down_proj:442.

What it responds to: the finite verb (a be-form or a contracted auxiliary) that comes
right after a subject pronoun or an existential "there"/"here". The strongest case is a
clitic contraction such as 's, 're, 'm, 've, 'll, 'd after a pronoun: "it's", "there's",
"we're", "I'm". Next come the plain be-forms "is/are/was/were" after "there"/"here" (e.g.
"there is"), then "is" after "it"/"this". Modals ("can", "will") and everything else give
about zero.

Why: the component writes into the residual stream at the position of the verb, where the
model is about to read the predicate of a clause whose subject was just named. Possessive
"'s" after a noun ("John's") does not fire, so the subject must be a pronoun.

The program looks only at the current token and the one before it, in the same document.
"""

READS = ()

SUBJECT_PRONOUNS = {"it","that", "what", "he", "she", "they", "we", "you", "i"}
EXISTENTIAL = {"there", "here"}
CLITICS = {"'s", "’s", "'re", "’re", "'m", "’m", "'ve", "’ve", "'ll", "’ll", "'d", "’d"}
BE_FORMS = {"is", "are", "was", "were", "exists", "exist"}


def step(carry, prefix, upstream):
    ids, docs, strs = prefix.token_ids, prefix.document_ids, prefix.token_strings
    if len(ids) < 2 or docs[-1] != docs[-2]:
        return None, 0.0
    before = strs[-2].strip().lower()
    word = strs[-1].strip().lower()
    value = 0.0
    if word in CLITICS:
        if before in EXISTENTIAL:
            value = 3.5
        elif before in SUBJECT_PRONOUNS:
            value = 2.0
    elif word in BE_FORMS:
        if before in EXISTENTIAL:
            value = 1.5
        elif before in ("it", "this"):
            value = 0.5
    return None, value

programs.luna:
"""Mark selected English subject-auxiliary patterns.

Contracted auxiliaries are especially strong after pronouns. Some uncontracted
copulas also stand out after "there", "it", or "this". This short rule
captures those patterns and leaves every other token at zero.
"""

READS = ()

S_COPULA_SUBJECTS = {
    "it", "that", "this", "there", "here", "what", "who", "he", "she",
}
PRONOUNS = {
    "i", "you", "we", "they", "he", "she", "it", "that", "this",
}
SINGULAR_COPULAS = {"is", "was"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == doc:
        previous = carry[1]
    current = prefix.token_strings[-1]
    word = current.strip().casefold()
    subject = previous.strip().casefold()
    value = 0.0

    if word in {"'s", "’s"} and subject in S_COPULA_SUBJECTS:
        value = 2.5
    elif word in {"'m", "’m"} and subject == "i":
        value = 1.4
    elif word in {"'re", "’re"} and subject in {"you", "we", "they"}:
        value = 1.8
    elif word in {"'ve", "’ve"} and subject in PRONOUNS:
        value = 1.7
    elif word in {"'ll", "’ll", "'d", "’d"} and subject in PRONOUNS:
        value = 1.3
    elif word in SINGULAR_COPULAS:
        if subject == "there":
            value = 1.5
        elif subject in {"it", "this"}:
            capitalized = previous.strip()[:1].isupper()
            value = 0.75 if capitalized else 0.3
    elif word == "are" and subject == "there":
        value = 1.2

    return (doc, current), float(value)

programs.sol:
"""A separate-space / formatting-boundary signal.
A space after indentation or an operator is strong, after a word or newline
weak.  Spaces after labels and linking words are intermediate.  Responses
are larger on short lines, early in a document and in Chinese/Japanese text.
End-of-text has the opposite sign.  A space-prefixed partial Unicode token
is estimated from the recent script; most other tokens are near zero.
"""
import math
READS = ()
MONTHS = set('january february march april may june july august september '
             'october november december jan feb mar apr jun jul aug sep '
             'sept oct nov dec'.split())
LABELS = set('no number num fig figure table tab eq equation chapter section '
             'sec part vol volume issue page pp p art article test lemma '
             'theorem corollary definition example exercise problem step '
             'line item'.split())
LINKS = {'of', 'to', 'from', 'by', 'on', 'as', 'and', 'or'}
CODE_INTRODUCERS = set('return yield print printf echo void param parameter '
                       'args type'.split())
# The preceding punctuation's contribution to the space response.
PUNCTUATION = (
    (',，、', 0.73), ('.。', 0.93), (':：', 1.52), ('=', 1.62),
    ('+', 1.49), ('-–—', 1.77), ('*', 1.43), ('([{<', 1.12),
    ('>', 1.57), (')]}', 1.03), ('\'"', 1.04), ('#', 1.87),
    ('•·▪', 1.39), ('|', 1.71),
)


def is_cjk(c):
    return '\u3400' <= c <= '\u9fff' or '\u3040' <= c <= '\u30ff'


def space_response(previous, recent, line_length, position):
    if position == 0:
        return 1.01
    word = previous.strip().lower()
    last = previous[-1:]
    log_position = math.log1p(position)
    value = -0.05 * log_position + 0.49 * math.exp(-line_length / 50)
    value += 1.91 * sum(map(is_cjk, recent)) / max(1, len(recent))
    value += 0.24 * sum(ord(c) > 127 for c in recent) / max(1, len(recent))
    if recent.endswith(('\\n', '\\r', '\\t')):
        value += 0.90
    elif previous.endswith(('\n', '\r')):
        value -= 0.21
    elif previous.isspace():
        if len(previous) == 1:
            value += 1.27
        else:
            value += 2.59 - 0.13 * log_position
            value += 0.18 * (len(previous) > 2)
    elif last.isalpha():
        base = -0.03
        if word in MONTHS:
            base = -0.23
        elif word in LABELS:
            base = 0.32
        elif word in LINKS:
            base = 0.25
        elif word in CODE_INTRODUCERS:
            base = 0.66
        elif len(previous) == 1:
            base = 0.35
        value += base + 0.027 * log_position + 0.38 * is_cjk(last)
    elif previous.strip().isnumeric():
        value += 1.10
    else:
        base = next((b for chars, b in PUNCTUATION if last in chars), 1.17)
        if last == ',' and '.' in previous:
            base -= 0.45
        value += base
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, 0)
    _, previous, recent, line_length, position = carry
    token = prefix.token_strings[-1]
    if token == ' ':
        value = space_response(previous, recent, line_length, position)
    elif token == '<|endoftext|>':
        value = -1.60
    elif token == ' \ufffd':
        cjk_fraction = sum(map(is_cjk, recent)) / max(1, len(recent))
        value = 1.30 if cjk_fraction > 0.08 else 0.24
    else:
        value = 0.0
    recent = (recent + token)[-256:]
    line_length = (len(token.rsplit('\n', 1)[-1]) if '\n' in token
                   else min(256, line_length + len(token)))
    return (doc, token, recent, line_length, position + 1), float(value)

programs.luna:
"""This small program predicts modest negative responses for token spellings
seen often among the component's stronger activations: acute o and three."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "ó":
        return None, -0.585
    if "ó" in token:
        return None, -0.225
    if token == "ό":
        return None, -0.3375
    if token == "3":
        return None, -0.1575
    return None, 0.0

programs.sol:
"""A negative detector for 份: a Chinese copy, portion, or share.

Counted copies give the largest response. Fixed compounds (identity,
year, backup, and so on) weaken it, particularly when merged into one
vocabulary token. Drafting/submitting documents is a weaker English cue.
Paper-document terms also receive smaller negative values; publishing
words give a small positive response.
There is also a byte-token artifact: the UTF-8 prefix shared by 份 and
Japanese 仮/仏 fires strongly before the character is complete.
"""
READS = ()

# Qwen's token for the incomplete UTF-8 bytes b"\xe4\xbb", shared by
# U+4EC0..U+4EFF (including 份, 仮 and 仏). Decoded alone it is just �.
SHARE_CHARACTER_BYTE_PREFIX = 6142

# Familiar compounds containing 份, when the WHOLE word is one token.
MERGED_COMPOUNDS = {
    '身份': -0.16,       # identity
    '的身份': -0.09,
    '身份证': -0.07,     # identity card
    '月份': -0.26,       # month
    '省份': -0.05,       # province
    '部份': -0.04,       # part
    '成份': -0.32,       # ingredients/composition
    '备份': -0.14,       # backup
    '份额': -0.85,       # share/portion
    '市场份额': -0.07,   # market share
    '基金份额': -0.49,   # fund shares
}

# The same character in a SPLIT compound still responds quite strongly.
IDENTITY_AND_YEAR = {'身', '年'}
FATE_ROLE_SUFFICIENCY = {'缘', '緣', '戏', '戲', '充'}
CONTENT_AND_BACKUP = {'水', '盐', '鹽', '备', '備'}
COUNTING = set('二两兩三四五六七八九十百千万亿每几幾')
DOCUMENT_SUBMISSION = {
    'submit', 'submits', 'submitted', 'submitting',
    'submission', 'submissions', 'filing',
}
PAPER_DOCUMENTS = {'原件', '附件', '清单', '问卷'}
PUBLICATION = {'publish', 'published', 'publishing', 'publishes'}
DRAFT_FORMS = {'drafted', 'drafting', 'drafts'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, was_byte_prefix = '', False
    else:
        _, tail, was_byte_prefix = carry
    raw = prefix.token_strings[-1]
    word = raw.strip()
    value = 0.001
    is_byte_prefix = prefix.token_ids[-1] == SHARE_CHARACTER_BYTE_PREFIX

    if is_byte_prefix:
        value = -2.85
    elif was_byte_prefix and word.startswith('�'):
        value = -0.78
    elif word in MERGED_COMPOUNDS:
        value = MERGED_COMPOUNDS[word]
    elif '股份' in word:  # stock shares
        value = -0.53
    elif word == '份':
        previous = tail[-1:]
        if previous in IDENTITY_AND_YEAR:
            value = -1.85 if previous == '年' else -1.55
        elif previous in FATE_ROLE_SUFFICIENCY:
            value = -2.4
        elif previous in CONTENT_AND_BACKUP:
            value = -3.0
        elif previous in COUNTING:
            value = -4.25
        else:
            value = -3.9
    elif word.endswith('一份'):
        value = -3.38 if word.startswith('了') else -3.67
    elif word == '这份':
        value = -3.82
    elif word == '那份':
        value = -3.43
    elif word.lower() == 'draft':
        if word != 'draft':
            value = -0.26
        else:
            value = -0.43 if raw.startswith(' ') else -0.18
            if tail.rstrip().lower().endswith('original'):
                value = -0.59
    elif word.lower() in DRAFT_FORMS:
        value = -0.26
    elif word.lower() in DOCUMENT_SUBMISSION:
        value = -0.22
    elif raw.startswith(' ') and word in {'document', 'documents'}:
        value = -0.12
    elif word in PAPER_DOCUMENTS:
        # Originals, attachments, lists and questionnaires are counted in 份.
        value = -0.4
    elif word == '纸质':  # paper-format, rather than electronic
        value = -0.8
    elif word.lower() in PUBLICATION:
        value = 0.14
    elif word == 'shares':
        value = -0.11

    return (document, (tail + raw)[-24:], is_byte_prefix), float(value)

programs.luna:
"""Approximate a sparse word cue for Chinese 份 and English draft.

The sampled strong responses cluster around 份 used for a copy or portion;
股份 and 份额 have milder responses. A few draft tokens are also modestly
negative. Other tokens get zero rather than guessing at their context-dependent
activations.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if "份" in token:
        if "股" in token:
            return None, -0.61
        if "额" in token:
            return None, -1.1
        return None, -3.8

    if "draft" in token.lower():
        return None, -0.59

    return None, 0.0

programs.sol:
"""A spelling-sensitive negative response, dominated by short ca fragments.

Strip whitespace and leading ASCII punctuation, then check spelling and case.
Bare ca is strong; merged ca fragments and longer ca-initial words are weaker.
A preceding uppercase fragment strengthens CA/ica continuations; a preceding
non-ASCII letter weakens lowercase ca. Never use context across documents.
Calcium and the Chinese characters/name 曹, 操, 曹操 have explicit responses.
Small, unrelated lexical activations are deliberately left at zero.
"""
import string

READS = ()
VOWELS = frozenset('aeiou')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip(string.punctuation)
    lower = word.lower()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    if lower == 'ca':
        if token.startswith(' '):
            if word == 'ca':
                value = -3.6
            else:
                value = -2.9 if word == 'Ca' else -2.5
        elif word == 'Ca':
            value = -2.4
        elif word == 'CA':
            value = -3.0 if previous.isupper() else -2.55
        else:
            non_ascii = any(c.isalpha() and not c.isascii() for c in previous)
            value = -2.0 if non_ascii else -2.9
    elif lower == 'ica':
        named = word.islower() and any(c.isupper() for c in previous)
        value = -1.6 if named else -1.05
    elif lower.endswith('ca') and len(word) == 3:
        value = -1.6 if lower[0] in VOWELS else -1.0
    elif lower.endswith('ca') and len(word) == 4:
        value = -0.8
    elif lower == 'caa' and word.isupper():
        value = -0.7
    elif lower in {'cas', 'cad'}:
        value = -0.8
    elif lower == 'calcium':
        value = -1.5
    elif lower.startswith('ca') and len(word) > 3:
        value = -0.1
    elif token == '曹':
        value = -4.1
    elif token == '操':
        value = -2.0
    elif token == '曹操':
        value = -2.4
    else:
        value = 0.0
    return None, value
